use anyhow::Result;
use serde::Deserialize;
use std::path::PathBuf;

#[derive(Debug, Deserialize, Clone)]
pub struct RefreshConfig {
    pub auto_refresh: Option<bool>,
    pub refresh_interval: Option<u64>,
    pub auto_fetch: Option<bool>,
    pub fetch_interval: Option<u64>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct Config {
    pub refresh: Option<RefreshConfig>,
}

impl Config {
    pub fn load() -> Result<Self> {
        let config_path = config_path();
        if config_path.exists() {
            let content = std::fs::read_to_string(&config_path)?;
            let config: Config = toml::from_str(&content)?;
            Ok(config)
        } else {
            Ok(Config { refresh: None })
        }
    }

    pub fn auto_refresh(&self) -> bool {
        self.refresh
            .as_ref()
            .and_then(|r| r.auto_refresh)
            .unwrap_or(true)
    }

    pub fn refresh_interval(&self) -> u64 {
        let val = self.refresh
            .as_ref()
            .and_then(|r| r.refresh_interval)
            .unwrap_or(10);
        val.max(1)
    }

    pub fn auto_fetch(&self) -> bool {
        self.refresh
            .as_ref()
            .and_then(|r| r.auto_fetch)
            .unwrap_or(true)
    }

    pub fn fetch_interval(&self) -> u64 {
        let val = self.refresh
            .as_ref()
            .and_then(|r| r.fetch_interval)
            .unwrap_or(60);
        val.max(10)
    }
}

fn config_path() -> PathBuf {
    dirs_config_path()
}

fn dirs_config_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home)
        .join(".config")
        .join("keifu")
        .join("config.toml")
}
EOF

