use anyhow::{Context, Result};
use git2::{Repository, Oid, Commit, BranchType};
use std::collections::HashMap;
use chrono::{DateTime, Local, TimeZone};

#[derive(Debug, Clone)]
pub struct CommitInfo {
    pub hash: String,
    pub short_hash: String,
    pub author: String,
    pub date: String,
    pub message: String,
    pub parents: Vec<String>,
    pub is_head: bool,
}

#[derive(Debug, Clone)]
pub struct BranchInfo {
    pub name: String,
    pub commit_hash: String,
    pub is_remote: bool,
    pub is_head: bool,
}

#[derive(Debug, Clone)]
pub struct FileChange {
    pub status: char,
    pub path: String,
    pub additions: usize,
    pub deletions: usize,
}

#[derive(Debug, Clone)]
pub struct CommitDetail {
    pub hash: String,
    pub author: String,
    pub date: String,
    pub parents: Vec<String>,
    pub message: String,
    pub files: Vec<FileChange>,
    pub total_additions: usize,
    pub total_deletions: usize,
    pub total_files: usize,
}

pub struct GitRepo {
    pub repo: Repository,
}

impl GitRepo {
    pub fn open() -> Result<Self> {
        let repo = Repository::discover(".")
            .with_context(|| "Git repository not found. Please run inside a Git repository.")?;
        Ok(GitRepo { repo })
    }

    pub fn repo_name(&self) -> String {
        let path = self.repo.workdir().or_else(|| self.repo.path().parent())
            .map(|p| p.to_path_buf())
            .unwrap_or_default();
        path.file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| "unknown".to_string())
    }

    pub fn current_branch(&self) -> String {
        match self.repo.head() {
            Ok(head) => {
                if head.is_branch() {
                    head.shorthand().unwrap_or("HEAD").to_string()
                } else {
                    let oid = head.target().unwrap_or(Oid::zero());
                    format!("{:.7}", oid)
                }
            }
            Err(_) => "HEAD".to_string(),
        }
    }

    pub fn head_hash(&self) -> Option<String> {
        self.repo.head().ok()
            .and_then(|h| h.target())
            .map(|oid| oid.to_string())
    }

    pub fn is_detached(&self) -> bool {
        self.repo.head_detached().unwrap_or(false)
    }

    pub fn has_uncommitted_changes(&self) -> bool {
        let mut opts = git2::StatusOptions::new();
        opts.include_untracked(false);
        opts.include_ignored(false);
        match self.repo.statuses(Some(&mut opts)) {
            Ok(statuses) => !statuses.is_empty(),
            Err(_) => false,
        }
    }

    pub fn get_branches(&self) -> Result<Vec<BranchInfo>> {
        let mut branches = Vec::new();
        let head_hash = self.head_hash().unwrap_or_default();

        // Local branches
        for branch in self.repo.branches(Some(BranchType::Local))? {
            let (branch, _) = branch?;
            let name = branch.name()?.unwrap_or("").to_string();
            if let Ok(reference) = branch.get().resolve() {
                if let Some(oid) = reference.target() {
                    let is_head = branch.is_head();
                    branches.push(BranchInfo {
                        name: name.clone(),
                        commit_hash: oid.to_string(),
                        is_remote: false,
                        is_head,
                    });
                }
            }
        }

        // Remote branches
        for branch in self.repo.branches(Some(BranchType::Remote))? {
            let (branch, _) = branch?;
            let name = branch.name()?.unwrap_or("").to_string();
            if let Ok(reference) = branch.get().resolve() {
                if let Some(oid) = reference.target() {
                    branches.push(BranchInfo {
                        name: name.clone(),
                        commit_hash: oid.to_string(),
                        is_remote: true,
                        is_head: false,
                    });
                }
            }
        }

        Ok(branches)
    }

    pub fn get_commits(&self, max_count: usize) -> Result<Vec<CommitInfo>> {
        let mut revwalk = self.repo.revwalk()?;
        revwalk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)?;
        revwalk.push_glob("refs/heads/*")?;
        revwalk.push_glob("refs/remotes/*")?;

        let head_hash = self.head_hash().unwrap_or_default();
        let mut commits = Vec::new();

        for oid in revwalk.take(max_count) {
            let oid = oid?;
            let commit = self.repo.find_commit(oid)?;
            let info = commit_to_info(&commit, &head_hash);
            commits.push(info);
        }

        Ok(commits)
    }

    pub fn get_commit_detail(&self, hash: &str) -> Result<CommitDetail> {
        let oid = Oid::from_str(hash)?;
        let commit = self.repo.find_commit(oid)?;

        let author = format!("{} <{}>", 
            commit.author().name().unwrap_or(""),
            commit.author().email().unwrap_or(""));

        let timestamp = commit.author().when().seconds();
        let dt: DateTime<Local> = Local.timestamp_opt(timestamp, 0).single()
            .unwrap_or_else(|| Local::now());
        let date = dt.format("%Y-%m-%d %H:%M:%S").to_string();

        let message = commit.message().unwrap_or("").to_string();
        let parents: Vec<String> = commit.parents()
            .map(|p| format!("{:.7}", p.id()))
            .collect();

        // Get diff
        let (files, total_additions, total_deletions) = get_commit_diff(&self.repo, &commit)?;
        let total_files = files.len();

        Ok(CommitDetail {
            hash: oid.to_string(),
            author,
            date,
            parents,
            message: message.trim_end().to_string(),
            files,
            total_additions,
            total_deletions,
            total_files,
        })
    }

    pub fn checkout(&self, target: &str) -> Result<String> {
        // First check if it's a local branch
        if let Ok(mut branch) = self.repo.find_branch(target, BranchType::Local) {
            let branch_ref = branch.get().name().unwrap_or("").to_string();
            let obj = self.repo.revparse_single(&branch_ref)?;
            self.repo.checkout_tree(&obj, None)?;
            self.repo.set_head(&branch_ref)?;
            return Ok(format!("Switched to branch '{}'", target));
        }

        // Check if it's a remote branch like origin/xxx
        if target.contains('/') {
            let parts: Vec<&str> = target.splitn(2, '/').collect();
            if parts.len() == 2 {
                let remote_name = parts[0];
                let branch_name = parts[1];

                // Check if local branch exists
                let local_exists = self.repo.find_branch(branch_name, BranchType::Local).is_ok();

                let remote_ref = format!("refs/remotes/{}/{}", remote_name, branch_name);
                let obj = self.repo.revparse_single(&remote_ref)?;
                let commit = obj.peel_to_commit()?;

                if local_exists {
                    // Force update local branch
                    let mut local_branch = self.repo.find_branch(branch_name, BranchType::Local)?;
                    let branch_ref = local_branch.get().name().unwrap_or("").to_string();
                    local_branch.get_mut().set_target(commit.id(), "fast-forward")?;
                    let obj2 = self.repo.revparse_single(&branch_ref)?;
                    self.repo.checkout_tree(&obj2, None)?;
                    self.repo.set_head(&branch_ref)?;
                    return Ok(format!("Updated and switched to branch '{}'", branch_name));
                } else {
                    // Create local branch
                    let mut new_branch = self.repo.branch(branch_name, &commit, false)?;
                    let branch_ref = new_branch.get().name().unwrap_or("").to_string();
                    // Set upstream
                    let _ = new_branch.set_upstream(Some(target));
                    let obj2 = self.repo.revparse_single(&branch_ref)?;
                    self.repo.checkout_tree(&obj2, None)?;
                    self.repo.set_head(&branch_ref)?;
                    return Ok(format!("Switched to new branch '{}'", branch_name));
                }
            }
        }

        // Try as a hash
        let obj = self.repo.revparse_single(target)?;
        self.repo.checkout_tree(&obj, None)?;
        self.repo.set_head_detached(obj.id())?;
        Ok(format!("HEAD detached at {:.7}", obj.id()))
    }

    pub fn create_branch(&self, name: &str, from_hash: &str) -> Result<String> {
        let oid = Oid::from_str(from_hash)?;
        let commit = self.repo.find_commit(oid)?;
        self.repo.branch(name, &commit, false)?;
        Ok(format!("Created branch '{}'", name))
    }

    pub fn delete_branch(&self, name: &str) -> Result<String> {
        let mut branch = self.repo.find_branch(name, BranchType::Local)?;
        branch.delete()?;
        Ok(format!("Deleted branch '{}'", name))
    }

    pub fn fetch(&self) -> Result<String> {
        let mut remote = self.repo.find_remote("origin")?;
        let callbacks = git2::RemoteCallbacks::new();
        let mut fetch_opts = git2::FetchOptions::new();
        fetch_opts.remote_callbacks(callbacks);
        fetch_opts.prune(git2::FetchPrune::On);

        let refspecs: Vec<String> = remote.fetch_refspecs()?
            .iter()
            .filter_map(|s| s.map(|s| s.to_string()))
            .collect();
        let refspec_refs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();

        remote.fetch(&refspec_refs, Some(&mut fetch_opts), None)?;
        Ok("Fetched from origin".to_string())
    }
}

fn commit_to_info(commit: &Commit, head_hash: &str) -> CommitInfo {
    let timestamp = commit.author().when().seconds();
    let dt: DateTime<Local> = Local.timestamp_opt(timestamp, 0).single()
        .unwrap_or_else(|| Local::now());
    let date = dt.format("%Y-%m-%d").to_string();

    let author = commit.author().name().unwrap_or("").to_string();
    let message = commit.message().unwrap_or("").lines().next().unwrap_or("").to_string();
    let hash = commit.id().to_string();
    let short_hash = format!("{:.7}", commit.id());
    let parents: Vec<String> = commit.parents().map(|p| p.id().to_string()).collect();
    let is_head = hash == head_hash;

    CommitInfo {
        hash,
        short_hash,
        author,
        date,
        message,
        parents,
        is_head,
    }
}

fn get_commit_diff(repo: &Repository, commit: &Commit) -> Result<(Vec<FileChange>, usize, usize)> {
    let tree = commit.tree()?;

    let parent_tree = if commit.parent_count() > 0 {
        Some(commit.parent(0)?.tree()?)
    } else {
        None
    };

    let mut diff_opts = git2::DiffOptions::new();
    diff_opts.ignore_whitespace(false);

    let diff = repo.diff_tree_to_tree(
        parent_tree.as_ref(),
        Some(&tree),
        Some(&mut diff_opts),
    )?;

    let mut files = Vec::new();
    let mut total_additions = 0usize;
    let mut total_deletions = 0usize;

    let mut stats_map: HashMap<String, (char, usize, usize)> = HashMap::new();

    diff.foreach(
        &mut |delta, _progress| {
            let status = match delta.status() {
                git2::Delta::Added => 'A',
                git2::Delta::Deleted => 'D',
                git2::Delta::Modified => 'M',
                git2::Delta::Renamed => 'R',
                git2::Delta::Copied => 'C',
                _ => 'U',
            };

            let path = delta.new_file().path()
                .or_else(|| delta.old_file().path())
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_default();

            // Check if binary
            let is_binary = delta.new_file().is_binary() || delta.old_file().is_binary();

            if !is_binary {
                stats_map.entry(path).or_insert((status, 0, 0));
            }
            true
        },
        None,
        None,
        Some(&mut |delta, _hunk, line| {
            let path = delta.new_file().path()
                .or_else(|| delta.old_file().path())
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_default();

            match line.origin() {
                '+' => {
                    if let Some(entry) = stats_map.get_mut(&path) {
                        entry.1 += 1;
                    }
                }
                '-' => {
                    if let Some(entry) = stats_map.get_mut(&path) {
                        entry.2 += 1;
                    }
                }
                _ => {}
            }
            true
        }),
    )?;

    // Collect and sort by path
    let mut entries: Vec<(String, (char, usize, usize))> = stats_map.into_iter().collect();
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    for (path, (status, additions, deletions)) in entries.iter().take(50) {
        total_additions += additions;
        total_deletions += deletions;
        files.push(FileChange {
            status: *status,
            path: path.clone(),
            additions: *additions,
            deletions: *deletions,
        });
    }

    // Also count for files beyond 50
    for (_, (_, additions, deletions)) in entries.iter().skip(50) {
        total_additions += additions;
        total_deletions += deletions;
    }

    Ok((files, total_additions, total_deletions))
}
