use std::collections::{HashMap, HashSet};
use crate::git::{CommitInfo, BranchInfo};

// Unicode box-drawing characters for graph
const GRAPH_CHARS: &[char] = &['●', '◉', '○'];

#[derive(Debug, Clone, PartialEq)]
pub enum GraphCell {
    Empty,
    Node,         // ●
    HeadNode,     // ◉
    Vertical,     // │
    Horizontal,   // ─
    MergeDown,    // ╮
    MergeUp,      // ╯
    BranchDown,   // ╭
    BranchUp,     // ╰
    Cross,        // ┼
    JoinLeft,     // ├
    JoinRight,    // ┤
    Space,        // ' '
}

impl GraphCell {
    pub fn to_char(&self) -> char {
        match self {
            GraphCell::Empty => ' ',
            GraphCell::Node => '●',
            GraphCell::HeadNode => '◉',
            GraphCell::Vertical => '│',
            GraphCell::Horizontal => '─',
            GraphCell::MergeDown => '╮',
            GraphCell::MergeUp => '╯',
            GraphCell::BranchDown => '╭',
            GraphCell::BranchUp => '╰',
            GraphCell::Cross => '┼',
            GraphCell::JoinLeft => '├',
            GraphCell::JoinRight => '┤',
            GraphCell::Space => ' ',
        }
    }
}

#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<(GraphCell, usize)>,  // (cell, color_index)
    pub commit_col: Option<usize>,
    pub commit_color: usize,
}

#[derive(Debug, Clone)]
pub struct CommitRow {
    pub commit: CommitInfo,
    pub graph: GraphRow,
    pub branches: Vec<BranchInfo>,
    pub selected_branch_idx: usize,  // which branch to show for multi-branch commits
}

pub struct GraphBuilder {
    // Tracks which columns are "active" (have a branch line)
    // Each entry is: Some(commit_hash) if active, None if empty
    active_columns: Vec<Option<String>>,
    // Color assignment per column
    column_colors: Vec<usize>,
    next_color: usize,
    num_colors: usize,
}

impl GraphBuilder {
    pub fn new() -> Self {
        GraphBuilder {
            active_columns: Vec::new(),
            column_colors: Vec::new(),
            next_color: 0,
            num_colors: 7, // number of distinct branch colors
        }
    }

    fn next_color(&mut self) -> usize {
        let c = self.next_color;
        self.next_color = (self.next_color + 1) % self.num_colors;
        c
    }

    fn find_column(&self, hash: &str) -> Option<usize> {
        self.active_columns.iter().position(|c| c.as_deref() == Some(hash))
    }

    fn find_empty_column(&self) -> Option<usize> {
        self.active_columns.iter().position(|c| c.is_none())
    }

    pub fn build_rows(&mut self, commits: &[CommitInfo], branches: &HashMap<String, Vec<BranchInfo>>) -> Vec<CommitRow> {
        let mut rows = Vec::new();

        // Initialize: put initial commits into columns
        // We process commits in order (newest first)

        for commit in commits {
            let hash = &commit.hash;

            // Find where this commit is in active columns
            let commit_col = self.find_column(hash);

            let col = if let Some(c) = commit_col {
                c
            } else {
                // This commit has no column yet - assign one
                let c = self.find_empty_column().unwrap_or(self.active_columns.len());
                if c == self.active_columns.len() {
                    self.active_columns.push(Some(hash.clone()));
                    self.column_colors.push(self.next_color());
                } else {
                    self.active_columns[c] = Some(hash.clone());
                    // keep existing color if reusing
                }
                c
            };

            let commit_color = self.column_colors[col];

            // Now build graph cells for this row
            // Before updating columns, record the current state
            let n_cols = self.active_columns.len();
            let mut cells: Vec<(GraphCell, usize)> = Vec::new();

            let num_parents = commit.parents.len();

            // For each current column, determine what happens
            // The commit is at column `col`
            // Its parents will occupy columns

            // Plan: 
            // - col stays for first parent
            // - additional parents get new columns to the right

            let parent_cols: Vec<usize> = if num_parents == 0 {
                // Root commit - col becomes empty
                vec![]
            } else if num_parents == 1 {
                // Single parent - col continues
                let parent_hash = &commit.parents[0];

                // Check if parent is already in a column
                if let Some(existing_col) = self.find_column(parent_hash) {
                    // Parent is already in a column - this is a merge point
                    // The current col will need to converge to existing_col
                    vec![existing_col]
                } else {
                    // Set col to parent
                    self.active_columns[col] = Some(parent_hash.clone());
                    vec![col]
                }
            } else {
                // Merge commit - multiple parents
                let mut pcols = Vec::new();

                for (i, parent_hash) in commit.parents.iter().enumerate() {
                    if i == 0 {
                        // First parent goes in current col
                        if let Some(existing_col) = self.find_column(parent_hash) {
                            // Already exists
                            pcols.push(existing_col);
                        } else {
                            self.active_columns[col] = Some(parent_hash.clone());
                            pcols.push(col);
                        }
                    } else {
                        // Other parents get new columns
                        if let Some(existing_col) = self.find_column(parent_hash) {
                            pcols.push(existing_col);
                        } else {
                            let new_col = self.find_empty_column()
                                .map(|c| {
                                    if c > col { c } else {
                                        // Use a column after existing ones
                                        self.active_columns.len()
                                    }
                                })
                                .unwrap_or(self.active_columns.len());

                            if new_col >= self.active_columns.len() {
                                self.active_columns.push(Some(parent_hash.clone()));
                                self.column_colors.push(self.next_color());
                            } else {
                                self.active_columns[new_col] = Some(parent_hash.clone());
                            }
                            pcols.push(new_col);
                        }
                    }
                }
                pcols
            };

            // Now build graph row
            let width = self.active_columns.len().max(col + 1);

            // Determine graph cells
            // Simple approach: draw cells for each column
            for c in 0..width {
                let color = if c < self.column_colors.len() { self.column_colors[c] } else { 0 };

                if c == col {
                    if commit.is_head {
                        cells.push((GraphCell::HeadNode, commit_color));
                    } else {
                        cells.push((GraphCell::Node, commit_color));
                    }
                } else if self.active_columns.get(c).and_then(|x| x.as_ref()).is_some() {
                    cells.push((GraphCell::Vertical, color));
                } else {
                    cells.push((GraphCell::Empty, 0));
                }
            }

            // Handle the case where col had no column before (new branch)
            // and single parent case where col disappears
            if num_parents == 0 {
                self.active_columns[col] = None;
            }

            let branch_list = branches.get(hash).cloned().unwrap_or_default();

            let graph_row = GraphRow {
                cells,
                commit_col: Some(col),
                commit_color,
            };

            rows.push(CommitRow {
                commit: commit.clone(),
                graph: graph_row,
                branches: branch_list,
                selected_branch_idx: 0,
            });

            // Clean up: remove columns that are no longer needed
            // (this is a simplified approach)
        }

        rows
    }
}

// More sophisticated graph builder using the approach of git log --graph
pub fn build_graph(commits: &[CommitInfo], branches: &HashMap<String, Vec<BranchInfo>>) -> Vec<CommitRow> {
    if commits.is_empty() {
        return Vec::new();
    }

    // Build a proper graph similar to git log --graph
    // Each row has a set of "lanes" - ongoing branches
    // A lane is identified by the commit hash it's heading towards

    struct Lane {
        target: String,  // commit hash this lane is heading to
        color: usize,
    }

    let mut lanes: Vec<Option<Lane>> = Vec::new();
    let mut next_color: usize = 0;
    let num_colors: usize = 7;

    let mut get_next_color = {
        let mut c = 0usize;
        move || -> usize {
            let r = c;
            c = (c + 1) % num_colors;
            r
        }
    };

    let mut rows: Vec<CommitRow> = Vec::new();

    for commit in commits {
        let hash = &commit.hash;

        // Find which lane this commit is in
        let commit_lane = lanes.iter().position(|l| {
            l.as_ref().map(|l| &l.target == hash).unwrap_or(false)
        });

        let (lane_idx, commit_color) = if let Some(idx) = commit_lane {
            let color = lanes[idx].as_ref().unwrap().color;
            (idx, color)
        } else {
            // New lane for this commit
            let idx = lanes.iter().position(|l| l.is_none()).unwrap_or(lanes.len());
            let color = get_next_color();
            if idx == lanes.len() {
                lanes.push(None);
            }
            lanes[idx] = Some(Lane { target: hash.clone(), color });
            (idx, color)
        };

        // Now build graph cells for the row BEFORE updating lanes
        let num_parents = commit.parents.len();

        // We need to figure out what happens to the lanes for the next row
        // and build the graph cells accordingly

        // The current commit is at lane_idx
        // First parent takes lane_idx
        // Additional parents (merge) get new lanes

        // Before we update lanes, record existing lanes for graph drawing
        let n_lanes = lanes.len();

        // Figure out where parents will go
        let mut parent_lanes: Vec<(usize, usize)> = Vec::new();  // (lane_idx, color)

        if num_parents == 0 {
            // Root commit - lane disappears
            lanes[lane_idx] = None;
        } else {
            for (i, parent_hash) in commit.parents.iter().enumerate() {
                if i == 0 {
                    // First parent takes current lane
                    let existing = lanes.iter().position(|l| {
                        l.as_ref().map(|l| &l.target == parent_hash).unwrap_or(false)
                    });

                    if let Some(existing_idx) = existing {
                        // Parent already has a lane - this lane merges into it
                        parent_lanes.push((existing_idx, lanes[existing_idx].as_ref().unwrap().color));
                        // We need to close lane_idx and continue on existing_idx
                        lanes[lane_idx] = None;
                    } else {
                        parent_lanes.push((lane_idx, commit_color));
                        lanes[lane_idx] = Some(Lane { target: parent_hash.clone(), color: commit_color });
                    }
                } else {
                    // Additional parents (merge commits)
                    let existing = lanes.iter().position(|l| {
                        l.as_ref().map(|l| &l.target == parent_hash).unwrap_or(false)
                    });

                    if let Some(existing_idx) = existing {
                        parent_lanes.push((existing_idx, lanes[existing_idx].as_ref().unwrap().color));
