    JoinRight,    // ┤
    Space,        // ' '
}

impl GraphCell {
    pub fn to_char(&self) -> char {
        match self {
            GraphCell::Empty => ' ',
            GraphCell::Node => '●',
            GraphCell::HeadNode => '◉',
            GraphCell::Vertical => '│',
            GraphCell::Horizontal => '─',
            GraphCell::MergeDown => '╮',
            GraphCell::MergeUp => '╯',
            GraphCell::BranchDown => '╭',
            GraphCell::BranchUp => '╰',
            GraphCell::Cross => '┼',
            GraphCell::JoinLeft => '├',
            GraphCell::JoinRight => '┤',
            GraphCell::Space => ' ',
        }
    }
}

#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<(GraphCell, usize)>,  // (cell, color_index)
    pub commit_col: Option<usize>,
    pub commit_color: usize,
}

#[derive(Debug, Clone)]
pub struct CommitRow {
    pub commit: CommitInfo,
    pub graph: GraphRow,
    pub branches: Vec<BranchInfo>,
    pub selected_branch_idx: usize,  // which branch to show for multi-branch commits
}

pub struct GraphBuilder {
    // Tracks which columns are "active" (have a branch line)
    // Each entry is: Some(commit_hash) if active, None if empty
    active_columns: Vec<Option<String>>,
    // Color assignment per column
    column_colors: Vec<usize>,
    next_color: usize,
    num_colors: usize,
}

impl GraphBuilder {
    pub fn new() -> Self {
        GraphBuilder {
            active_columns: Vec::new(),
            column_colors: Vec::new(),
            next_color: 0,
            num_colors: 7, // number of distinct branch colors
        }
    }

    fn next_color(&mut self) -> usize {
        let c = self.next_color;
        self.next_color = (self.next_color + 1) % self.num_colors;
        c
    }

    fn find_column(&self, hash: &str) -> Option<usize> {
        self.active_columns.iter().position(|c| c.as_deref() == Some(hash))
    }

    fn find_empty_column(&self) -> Option<usize> {
        self.active_columns.iter().position(|c| c.is_none())
    }

    pub fn build_rows(&mut self, commits: &[CommitInfo], branches: &HashMap<String, Vec<BranchInfo>>) -> Vec<CommitRow> {
        let mut rows = Vec::new();

        // Initialize: put initial commits into columns
        // We process commits in order (newest first)

        for commit in commits {
            let hash = &commit.hash;

            // Find where this commit is in active columns
            let commit_col = self.find_column(hash);

            let col = if let Some(c) = commit_col {
                c
            } else {
                // This commit has no column yet - assign one
                let c = self.find_empty_column().unwrap_or(self.active_columns.len());
                if c == self.active_columns.len() {
                    self.active_columns.push(Some(hash.clone()));
                    self.column_colors.push(self.next_color());
                } else {
                    self.active_columns[c] = Some(hash.clone());
                    // keep existing color if reusing
                }
                c
            };

            let commit_color = self.column_colors[col];

            // Now build graph cells for this row
            // Before updating columns, record the current state
            let n_cols = self.active_columns.len();
            let mut cells: Vec<(GraphCell, usize)> = Vec::new();

            let num_parents = commit.parents.len();

            // For each current column, determine what happens
            // The commit is at column `col`
            // Its parents will occupy columns

            // Plan: 
            // - col stays for first parent
            // - additional parents get new columns to the right

            let parent_cols: Vec<usize> = if num_parents == 0 {
                // Root commit - col becomes empty
                vec![]
            } else if num_parents == 1 {
                // Single parent - col continues
                let parent_hash = &commit.parents[0];

                // Check if parent is already in a column
                if let Some(existing_col) = self.find_column(parent_hash) {
                    // Parent is already in a column - this is a merge point
                    // The current col will need to converge to existing_col
                    vec![existing_col]
                } else {
                    // Set col to parent
                    self.active_columns[col] = Some(parent_hash.clone());
                    vec![col]
                }
            } else {
                // Merge commit - multiple parents
                let mut pcols = Vec::new();

                for (i, parent_hash) in commit.parents.iter().enumerate() {
                    if i == 0 {
                        // First parent goes in current col
                        if let Some(existing_col) = self.find_column(parent_hash) {
                            // Already exists
                            pcols.push(existing_col);
                        } else {
                            self.active_columns[col] = Some(parent_hash.clone());
                            pcols.push(col);
                        }
                    } else {
                        // Other parents get new columns
                        if let Some(existing_col) = self.find_column(parent_hash) {
                            pcols.push(existing_col);
                        } else {
                            let new_col = self.find_empty_column()
                                .map(|c| {
                                    if c > col { c } else {
                                        // Use a column after existing ones
                                        self.active_columns.len()
                                    }
                                })
                                .unwrap_or(self.active_columns.len());

                            if new_col >= self.active_columns.len() {
                                self.active_columns.push(Some(parent_hash.clone()));
                                self.column_colors.push(self.next_color());
                            } else {
                                self.active_columns[new_col] = Some(parent_hash.clone());
                            }
                            pcols.push(new_col);
                        }
                    }
                }
                pcols
            };

            // Now build graph row
            let width = self.active_columns.len().max(col + 1);

            // Determine graph cells
            // Simple approach: draw cells for each column
            for c in 0..width {
                let color = if c < self.column_colors.len() { self.column_colors[c] } else { 0 };

                if c == col {
                    if commit.is_head {
                        cells.push((GraphCell::HeadNode, commit_color));
                    } else {
                        cells.push((GraphCell::Node, commit_color));
                    }
                } else if self.active_columns.get(c).and_then(|x| x.as_ref()).is_some() {
                    cells.push((GraphCell::Vertical, color));
                } else {
                    cells.push((GraphCell::Empty, 0));
                }
            }

            // Handle the case where col had no column before (new branch)
            // and single parent case where col disappears
            if num_parents == 0 {
                self.active_columns[col] = None;
            }

            let branch_list = branches.get(hash).cloned().unwrap_or_default();

            let graph_row = GraphRow {
                cells,
                commit_col: Some(col),
                commit_color,
            };

            rows.push(CommitRow {
                commit: commit.clone(),
                graph: graph_row,
                branches: branch_list,
                selected_branch_idx: 0,
            });

            // Clean up: remove columns that are no longer needed
            // (this is a simplified approach)
        }

        rows
    }
}

// More sophisticated graph builder using the approach of git log --graph
pub fn build_graph(commits: &[CommitInfo], branches: &HashMap<String, Vec<BranchInfo>>) -> Vec<CommitRow> {
    if commits.is_empty() {
        return Vec::new();
    }

    // Build a proper graph similar to git log --graph
    // Each row has a set of "lanes" - ongoing branches
    // A lane is identified by the commit hash it's heading towards

    struct Lane {
        target: String,  // commit hash this lane is heading to
        color: usize,
    }

    let mut lanes: Vec<Option<Lane>> = Vec::new();
    let mut next_color: usize = 0;
    let num_colors: usize = 7;

    let mut get_next_color = {
        let mut c = 0usize;
        move || -> usize {
            let r = c;
            c = (c + 1) % num_colors;
            r
        }
    };

    let mut rows: Vec<CommitRow> = Vec::new();

    for commit in commits {
        let hash = &commit.hash;

        // Find which lane this commit is in
        let commit_lane = lanes.iter().position(|l| {
            l.as_ref().map(|l| &l.target == hash).unwrap_or(false)
        });

        let (lane_idx, commit_color) = if let Some(idx) = commit_lane {
            let color = lanes[idx].as_ref().unwrap().color;
            (idx, color)
        } else {
            // New lane for this commit
            let idx = lanes.iter().position(|l| l.is_none()).unwrap_or(lanes.len());
            let color = get_next_color();
            if idx == lanes.len() {
                lanes.push(None);
            }
            lanes[idx] = Some(Lane { target: hash.clone(), color });
            (idx, color)
        };

        // Now build graph cells for the row BEFORE updating lanes
        let num_parents = commit.parents.len();

        // We need to figure out what happens to the lanes for the next row
        // and build the graph cells accordingly

        // The current commit is at lane_idx
        // First parent takes lane_idx
        // Additional parents (merge) get new lanes

        // Before we update lanes, record existing lanes for graph drawing
        let n_lanes = lanes.len();

        // Figure out where parents will go
        let mut parent_lanes: Vec<(usize, usize)> = Vec::new();  // (lane_idx, color)

        if num_parents == 0 {
            // Root commit - lane disappears
            lanes[lane_idx] = None;
        } else {
            for (i, parent_hash) in commit.parents.iter().enumerate() {
                if i == 0 {
                    // First parent takes current lane
                    let existing = lanes.iter().position(|l| {
                        l.as_ref().map(|l| &l.target == parent_hash).unwrap_or(false)
                    });

                    if let Some(existing_idx) = existing {
                        // Parent already has a lane - this lane merges into it
                        parent_lanes.push((existing_idx, lanes[existing_idx].as_ref().unwrap().color));
                        // We need to close lane_idx and continue on existing_idx
                        lanes[lane_idx] = None;
                    } else {
                        parent_lanes.push((lane_idx, commit_color));
                        lanes[lane_idx] = Some(Lane { target: parent_hash.clone(), color: commit_color });
                    }
                } else {
                    // Additional parents (merge commits)
                    let existing = lanes.iter().position(|l| {
                        l.as_ref().map(|l| &l.target == parent_hash).unwrap_or(false)
                    });

                    if let Some(existing_idx) = existing {
                        parent_lanes.push((existing_idx, lanes[existing_idx].as_ref().unwrap().color));
                    } else {
                        // Find a new lane
                        let new_idx = lanes.iter().position(|l| l.is_none())
                            .unwrap_or(lanes.len());
                        let new_color = get_next_color();
                        if new_idx == lanes.len() {
                            lanes.push(Some(Lane { target: parent_hash.clone(), color: new_color }));
                        } else {
                            lanes[new_idx] = Some(Lane { target: parent_hash.clone(), color: new_color });
                        }
                        parent_lanes.push((new_idx, new_color));
                    }
                }
            }
        }

        // Build graph cells
        // For each active lane position, draw appropriate character
        let new_n_lanes = lanes.len();
        let cell_width = n_lanes.max(new_n_lanes).max(lane_idx + 1);

        let mut cells: Vec<(GraphCell, usize)> = Vec::new();

        for c in 0..cell_width {
            let old_lane = if c < n_lanes { lanes_get_old(&lanes, c) } else { None };
            // Note: we've already updated lanes at this point for parents
            // We need to restore...
            // Actually this approach is getting complex. Let's just draw simple vertical lines for now.

            let lcolor = if c < lanes.len() {
                lanes.get(c).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or(0)
            } else { 0 };

            if c == lane_idx {
                if commit.is_head {
                    cells.push((GraphCell::HeadNode, commit_color));
                } else {
                    cells.push((GraphCell::Node, commit_color));
                }
            } else if c < lanes.len() && lanes[c].is_some() {
                cells.push((GraphCell::Vertical, lcolor));
            } else {
                cells.push((GraphCell::Empty, 0));
            }
        }

        let branch_list = branches.get(hash).cloned().unwrap_or_default();

        rows.push(CommitRow {
            commit: commit.clone(),
            graph: GraphRow {
                cells,
                commit_col: Some(lane_idx),
                commit_color,
            },
            branches: branch_list,
            selected_branch_idx: 0,
        });
    }

    rows
}

fn lanes_get_old<T>(v: &Vec<T>, idx: usize) -> Option<&T> {
    v.get(idx)
}

// Proper graph building that matches git log --graph style
pub fn build_graph_v2(commits: &[CommitInfo], branches: &HashMap<String, Vec<BranchInfo>>) -> Vec<CommitRow> {
    if commits.is_empty() {
        return Vec::new();
    }

    let num_colors: usize = 7;
    let mut next_color: usize = 0;

    // lanes[i] = Some(target_hash) means lane i is active and heading toward target_hash
    let mut lane_targets: Vec<Option<String>> = Vec::new();
    let mut lane_colors: Vec<usize> = Vec::new();

    let mut alloc_color = || -> usize {
        let c = next_color;
        next_color = (next_color + 1) % num_colors;
        c
    };

    let mut rows: Vec<CommitRow> = Vec::new();

    for commit in commits {
        let hash = &commit.hash;
        let parents = &commit.parents;

        // Find the lane for this commit
        let my_lane = lane_targets.iter().position(|t| t.as_deref() == Some(hash.as_str()));

        let (my_lane_idx, my_color) = if let Some(idx) = my_lane {
            let c = lane_colors[idx];
            (idx, c)
        } else {
            // Insert in first empty slot or at end
            let idx = lane_targets.iter().position(|t| t.is_none()).unwrap_or_else(|| {
                lane_targets.push(None);
                lane_colors.push(0);
                lane_targets.len() - 1
            });
            let c = alloc_color();
            lane_colors[idx] = c;
            lane_targets[idx] = Some(hash.clone());
            (idx, c)
        };

        // Build the pre-update snapshot of lanes  
        let pre_lanes: Vec<Option<String>> = lane_targets.clone();
        let pre_colors: Vec<usize> = lane_colors.clone();

        // Update lanes for next iteration:
        // - The current lane (my_lane_idx) gets first parent
        // - Additional parents get new lanes
        // - If no parents, current lane closes

        let mut my_lane_parent_closed = false;
        let mut extra_parent_lanes: Vec<(usize, usize)> = Vec::new(); // (lane_idx, color)

        if parents.is_empty() {
            lane_targets[my_lane_idx] = None;
        } else {
            let first_parent = &parents[0];

            // Check if first parent already has a lane
            let existing = lane_targets.iter().position(|t| t.as_deref() == Some(first_parent.as_str()));

            if let Some(existing_idx) = existing {
                if existing_idx != my_lane_idx {
                    // First parent already has a lane - close current lane and converge
                    lane_targets[my_lane_idx] = None;
                    my_lane_parent_closed = true;
                }
                // else: same lane, nothing changes for first parent
            } else {
                lane_targets[my_lane_idx] = Some(first_parent.clone());
                // keep color
            }

            // Handle additional parents
            for parent in parents.iter().skip(1) {
                let existing = lane_targets.iter().position(|t| t.as_deref() == Some(parent.as_str()));

                if let Some(existing_idx) = existing {
                    extra_parent_lanes.push((existing_idx, lane_colors[existing_idx]));
                } else {
                    let new_idx = lane_targets.iter().position(|t| t.is_none()).unwrap_or_else(|| {
                        lane_targets.push(None);
                        lane_colors.push(0);
                        lane_targets.len() - 1
                    });
                    let new_color = alloc_color();
                    lane_targets[new_idx] = Some(parent.clone());
                    lane_colors[new_idx] = new_color;
                    extra_parent_lanes.push((new_idx, new_color));
                }
            }
        }

        // Now build graph cells based on pre_lanes and what we're drawing
        let merge_parent_lanes: Vec<usize> = extra_parent_lanes.iter().map(|(i, _)| *i).collect();

        // Width of graph
        let width = pre_lanes.len().max(lane_targets.len()).max(my_lane_idx + 1);

        // Build graph row with merge lines if needed
        let mut graph_cells: Vec<(GraphCell, usize)> = Vec::new();

        // For merge commits, we need to show horizontal connecting lines
        let is_merge = parents.len() > 1;

        // Determine merge connect columns
        let merge_cols: Vec<usize> = if is_merge {
            extra_parent_lanes.iter().map(|(c, _)| *c).collect()
        } else {
            vec![]
        };

        let min_merge_col = merge_cols.iter().copied().min().unwrap_or(width);
        let max_merge_col = merge_cols.iter().copied().max().unwrap_or(0);

        // Also handle parent convergence
        // If first parent already has a lane at existing_idx, we converge
        let converge_col = if parents.is_empty() || my_lane_parent_closed {
            None
        } else {
            let first_parent = &parents[0];
            lane_targets.iter().position(|t| t.as_deref() == Some(first_parent.as_str()))
                .filter(|&idx| idx != my_lane_idx)
        };

        for c in 0..width {
            let pre_color = pre_colors.get(c).copied().unwrap_or(0);
            let post_color = lane_colors.get(c).copied().unwrap_or(0);
            let pre_active = pre_lanes.get(c).and_then(|x| x.as_ref()).is_some();
            let post_active = lane_targets.get(c).and_then(|x| x.as_ref()).is_some();

            if c == my_lane_idx {
                if commit.is_head {
                    graph_cells.push((GraphCell::HeadNode, my_color));
                } else {
                    graph_cells.push((GraphCell::Node, my_color));
                }
                continue;
            }

            if is_merge {
                if merge_cols.contains(&c) {
                    // This is a merge target column
                    let merge_color = extra_parent_lanes.iter()
                        .find(|(ci, _)| *ci == c)
                        .map(|(_, col)| *col)
                        .unwrap_or(0);

                    if c > my_lane_idx {
                        graph_cells.push((GraphCell::MergeDown, merge_color));
                    } else {
                        graph_cells.push((GraphCell::MergeDown, merge_color));
                    }
                    continue;
                }

                // Are we between node and a merge target?
                if c > my_lane_idx && c < max_merge_col && max_merge_col > my_lane_idx {
                    // Draw horizontal line between node and merge targets
                    if pre_active {
                        graph_cells.push((GraphCell::Cross, pre_color));
                    } else {
                        let merge_color = extra_parent_lanes.iter()
                            .find(|(ci, _)| *ci == max_merge_col)
                            .map(|(_, col)| *col)
                            .unwrap_or(0);
                        graph_cells.push((GraphCell::Horizontal, merge_color));
                    }
                    continue;
                }
            }

            if pre_active {
                graph_cells.push((GraphCell::Vertical, pre_color));
            } else {
                graph_cells.push((GraphCell::Empty, 0));
            }
        }

        // Trim trailing empty cells
        while graph_cells.last().map(|(c, _)| c == &GraphCell::Empty).unwrap_or(false) {
            graph_cells.pop();
        }

        let branch_list = branches.get(hash).cloned().unwrap_or_default();

        rows.push(CommitRow {
            commit: commit.clone(),
            graph: GraphRow {
                cells: graph_cells,
                commit_col: Some(my_lane_idx),
                commit_color: my_color,
            },
            branches: branch_list,
            selected_branch_idx: 0,
        });
    }

    rows
}
