/// Represents a single character cell in the graph with its color
#[derive(Debug, Clone, PartialEq)]
pub struct GraphCell {
    pub ch: char,
    pub color: u8,  // terminal color index (0 = default/no color)
}

impl GraphCell {
    pub fn new(ch: char, color: u8) -> Self {
        GraphCell { ch, color }
    }

    pub fn space() -> Self {
        GraphCell { ch: ' ', color: 0 }
    }
}

/// Represents one visual row in the graph (may be commit or connector)
#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<GraphCell>,  // 2 cells per lane (char + separator), trimmed
    pub is_connector: bool,
}

/// Combined commit+graph row for display
#[derive(Debug, Clone)]
pub struct CommitRow {
    pub commit: CommitInfo,
    pub graph: GraphRow,
    pub branches: Vec<BranchInfo>,
    pub selected_branch_idx: usize,
}

/// A "pseudo" row used to represent connector rows
/// These are inserted between commit rows when lanes converge
#[derive(Debug, Clone)]
pub struct ConnectorRow {
    pub graph: GraphRow,
}

/// Items in the display list
#[derive(Debug, Clone)]
pub enum DisplayRow {
    Commit(CommitRow),
    Connector(ConnectorRow),
}

fn lane_color(lane_idx: usize) -> u8 {
    LANE_COLORS[lane_idx % LANE_COLORS.len()]
}

/// Lane state during graph building
#[derive(Debug, Clone)]
struct Lane {
    /// The commit hash this lane is heading towards
    target: String,
    /// The color assigned to this lane
    color: u8,
    /// Is this lane "pending close" (converged to another lane)?  
    pending_close: bool,
    /// If pending_close, which lane is it converging into
    converge_to: Option<usize>,
}

/// Build the complete list of display rows (commits + connectors)
pub fn build_display_rows(
    commits: &[CommitInfo],
    branches: &HashMap<String, Vec<BranchInfo>>,
) -> Vec<DisplayRow> {
    if commits.is_empty() {
        return Vec::new();
    }

    let mut lanes: Vec<Option<Lane>> = Vec::new();
    let mut next_color_idx: usize = 0;

    let mut alloc_lane_color = || -> u8 {
        let c = LANE_COLORS[next_color_idx % LANE_COLORS.len()];
        next_color_idx += 1;
        c
    };

    let mut result: Vec<DisplayRow> = Vec::new();

    for commit in commits {
        let hash = &commit.hash;
        let parents = &commit.parents;

        // Check if we need to draw a connector row BEFORE this commit
        // A connector is needed when ALL active lanes target this commit
        // (including pending-close lanes that also converge to the same target)
        let all_target_this = {
