                let targeting_count = lanes.iter()
                    .filter_map(|l| l.as_ref())
                    .filter(|l| l.target == *hash)
                    .count();
                targeting_count > 1
            }
        };

        if all_target_this {
            // Draw connector row before this commit
            let connector = build_connector_row(&lanes);
            result.push(DisplayRow::Connector(ConnectorRow { graph: connector }));
            // Close pending lanes and compact
            close_and_compact_lanes(&mut lanes);
