fn get_final_target<'a>(lane: &'a Lane, _lanes: &[Option<Lane>]) -> &'a str {
    &lane.target
}

fn active_lane_count(lanes: &[Option<Lane>]) -> usize {
    lanes.iter().filter(|l| l.is_some()).count()
}

fn close_and_compact_lanes(lanes: &mut Vec<Option<Lane>>) {
    // Find the surviving lane (the one that's not pending-close and has the same target)
    // Actually we just need to close all pending lanes
    for lane in lanes.iter_mut() {
        if let Some(l) = lane {
            if l.pending_close {
                *lane = None;
            }
        }
    }

    // Trim trailing None lanes
    while lanes.last().map(|l| l.is_none()).unwrap_or(false) {
        lanes.pop();
    }
}

fn build_commit_row(
    lanes: &[Option<Lane>],
    commit: &CommitInfo,
    my_lane_idx: usize,
    my_color: u8,
    extra_parents: &[(usize, u8)],
) -> GraphRow {
    let max_merge_col = extra_parents.iter().map(|(i, _)| *i).max().unwrap_or(0);
    let has_merge = !extra_parents.is_empty();
    let rightmost_merge_color = extra_parents.last().map(|(_, c)| *c).unwrap_or(my_color);

    // Determine row width
    let width = lanes.len().max(my_lane_idx + 1).max(if has_merge { max_merge_col + 1 } else { 0 });

    let mut cells: Vec<GraphCell> = Vec::new();

    for c in 0..width {
        let lane_color_at = |col: usize| -> u8 {
            lanes.get(col).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or(0)
        };

        let is_active = lanes.get(c).and_then(|l| l.as_ref()).is_some();

        let ch_color = if c == my_lane_idx {
            // The commit node
            let node_ch = if commit.is_head { '◉' } else { '●' };
            cells.push(GraphCell::new(node_ch, my_color));
        } else if has_merge && c > my_lane_idx && c <= max_merge_col {
            // Between node and rightmost merge parent
            if extra_parents.iter().any(|(i, _)| *i == c) {
                // This is a merge parent lane
                let mc = extra_parents.iter().find(|(i, _)| *i == c).map(|(_, col)| *col).unwrap_or(0);
                cells.push(GraphCell::new('╮', mc));
            } else if is_active {
                // Active lane being crossed
                cells.push(GraphCell::new('┼', lane_color_at(c)));
            } else {
                // Empty space in horizontal connection
                cells.push(GraphCell::new('─', rightmost_merge_color));
            }
        } else if is_active {
            cells.push(GraphCell::new('│', lane_color_at(c)));
        } else {
            cells.push(GraphCell::space());
        };

        // Add separator (space or ─ for merge connection)
        if c < width - 1 {
            if has_merge && c >= my_lane_idx && c < max_merge_col {
                // In the merge connection zone - use horizontal line
                cells.push(GraphCell::new('─', rightmost_merge_color));
            } else {
                cells.push(GraphCell::space());
            }
        }
    }

    // Trim trailing spaces
    while cells.last().map(|c| c.ch == ' ').unwrap_or(false) {
        cells.pop();
    }

    GraphRow { cells, is_connector: false }
}

fn build_connector_row(lanes: &[Option<Lane>]) -> GraphRow {
    // Find the surviving lane (lowest index non-pending lane that targets the common commit)
    // and the closing lanes (pending-close + other lanes all targeting same)

    // First, find what commit all lanes are targeting
