    lanes: &[Option<Lane>],
    commit: &CommitInfo,
    my_lane_idx: usize,
    my_color: u8,
    extra_parents: &[(usize, u8)],
) -> GraphRow {
    let max_merge_col = extra_parents.iter().map(|(i, _)| *i).max().unwrap_or(0);
    let has_merge = !extra_parents.is_empty();
    let rightmost_merge_color = extra_parents.last().map(|(_, c)| *c).unwrap_or(my_color);

    // Determine row width
    let width = lanes.len().max(my_lane_idx + 1).max(if has_merge { max_merge_col + 1 } else { 0 });

    let mut cells: Vec<GraphCell> = Vec::new();

    for c in 0..width {
        let lane_color_at = |col: usize| -> u8 {
            lanes.get(col).and_then(|l| l.as_ref()).map(|l| l.color).unwrap_or(0)
