        if c < width - 1 {
            if has_merge && c >= my_lane_idx && c < max_merge_col {
                // In the merge connection zone - use horizontal line
                cells.push(GraphCell::new('─', rightmost_merge_color));
            } else {
                cells.push(GraphCell::space());
            }
        }
    }

