fn build_connector_row(lanes: &[Option<Lane>]) -> GraphRow {
    // Find the surviving lane (lowest index non-pending lane that targets the common commit)
    // and the closing lanes (pending-close + other lanes all targeting same)

    // First, find what commit all lanes are targeting
    let common_target = lanes.iter()
        .filter_map(|l| l.as_ref())
        .map(|l| l.target.clone())
        .next()
        .unwrap_or_default();

    // Find all lane indices involved
    let involved_lanes: Vec<usize> = lanes.iter().enumerate()
        .filter_map(|(i, l)| l.as_ref().map(|_| i))
        .collect();

    if involved_lanes.is_empty() {
        return GraphRow { cells: Vec::new(), is_connector: true };
    }

    let min_lane = *involved_lanes.first().unwrap();
    let max_lane = *involved_lanes.last().unwrap();

    // The surviving lane is the leftmost (min_lane)
    let surviving_color = lanes[min_lane].as_ref().map(|l| l.color).unwrap_or(0);

    // The rightmost closing lane's color
    let rightmost_color = lanes[max_lane].as_ref().map(|l| l.color).unwrap_or(0);

