            // Not involved in this connector - draw nothing? Or ─?
            // Between involved lanes, draw ─
            if c > min_lane && c < max_lane {
                cells.push(GraphCell::new('─', rightmost_color));
            } else {
                cells.push(GraphCell::space());
            }
        }

        // Add separator
        if c < width - 1 {
            if c >= min_lane && c < max_lane {
                // In connector range: use ─
                cells.push(GraphCell::new('─', rightmost_color));
            } else {
                cells.push(GraphCell::space());
            }
        }
    }

    // Trim trailing spaces
    while cells.last().map(|c| c.ch == ' ').unwrap_or(false) {
        cells.pop();
    }

    GraphRow { cells, is_connector: true }
}

