use std::collections::HashMap;
use crate::git::{CommitInfo, BranchInfo};

/// Color palette for branch lanes (terminal 256-color indices)
pub const LANE_COLORS: &[u8] = &[12, 2, 5, 3, 1, 14, 10];

/// Represents a single character cell in the graph with its color
#[derive(Debug, Clone, PartialEq)]
pub struct GraphCell {
    pub ch: char,
    pub color: u8,  // terminal color index (0 = default/no color)
}

impl GraphCell {
    pub fn new(ch: char, color: u8) -> Self {
        GraphCell { ch, color }
    }

    pub fn space() -> Self {
        GraphCell { ch: ' ', color: 0 }
    }
}

/// Represents one visual row in the graph (may be commit or connector)
#[derive(Debug, Clone)]
pub struct GraphRow {
    pub cells: Vec<GraphCell>,  // 2 cells per lane (char + separator), trimmed
    pub is_connector: bool,
}

/// Combined commit+graph row for display
#[derive(Debug, Clone)]
pub struct CommitRow {
    pub commit: CommitInfo,
    pub graph: GraphRow,
    pub branches: Vec<BranchInfo>,
    pub selected_branch_idx: usize,
}

/// A "pseudo" row used to represent connector rows
/// These are inserted between commit rows when lanes converge
#[derive(Debug, Clone)]
pub struct ConnectorRow {
    pub graph: GraphRow,
}

/// Items in the display list
#[derive(Debug, Clone)]
pub enum DisplayRow {
    Commit(CommitRow),
    Connector(ConnectorRow),
}

fn lane_color(lane_idx: usize) -> u8 {
    LANE_COLORS[lane_idx % LANE_COLORS.len()]
}

/// Lane state during graph building
#[derive(Debug, Clone)]
struct Lane {
    /// The commit hash this lane is heading towards
    target: String,
    /// The color assigned to this lane
    color: u8,
    /// Is this lane "pending close" (converged to another lane)?  
    pending_close: bool,
    /// If pending_close, which lane is it converging into
    converge_to: Option<usize>,
}

/// Build the complete list of display rows (commits + connectors)
pub fn build_display_rows(
    commits: &[CommitInfo],
    branches: &HashMap<String, Vec<BranchInfo>>,
) -> Vec<DisplayRow> {
    if commits.is_empty() {
        return Vec::new();
    }

    let mut lanes: Vec<Option<Lane>> = Vec::new();
    let mut next_color_idx: usize = 0;

    let mut alloc_lane_color = || -> u8 {
        let c = LANE_COLORS[next_color_idx % LANE_COLORS.len()];
        next_color_idx += 1;
        c
    };

    let mut result: Vec<DisplayRow> = Vec::new();

    for commit in commits {
        let hash = &commit.hash;
        let parents = &commit.parents;

        // Check if we need to draw a connector row BEFORE this commit
        // A connector is needed when ALL active lanes target this commit
        // (including pending-close lanes that also converge to the same target)
        let all_target_this = {
            let active_lanes: Vec<&Lane> = lanes.iter()
                .filter_map(|l| l.as_ref())
                .filter(|l| !l.pending_close || get_final_target(l, &lanes) == hash.as_str())
                .collect();

            let active_count = active_lanes.len();
            let target_count = active_lanes.iter()
                .filter(|l| l.target == *hash || 
                    (l.pending_close && get_final_target(l, &lanes) == hash.as_str()))
                .count();

            // All lanes target this commit AND there are multiple converging lanes
            active_count > 0 && target_count == active_count && {
                let targeting_count = lanes.iter()
                    .filter_map(|l| l.as_ref())
                    .filter(|l| l.target == *hash)
                    .count();
                targeting_count > 1
            }
        };

        if all_target_this {
            // Draw connector row before this commit
            let connector = build_connector_row(&lanes);
            result.push(DisplayRow::Connector(ConnectorRow { graph: connector }));
            // Close pending lanes and compact
            close_and_compact_lanes(&mut lanes);
        }

        // Find or create the lane for this commit
        let my_lane_idx = {
            let existing = lanes.iter().position(|l| {
                l.as_ref().map(|l| l.target == *hash && !l.pending_close).unwrap_or(false)
            });

            if let Some(idx) = existing {
                idx
            } else {
                // Find first empty slot or create new lane
                let idx = lanes.iter().position(|l| l.is_none()).unwrap_or_else(|| {
                    lanes.push(None);
                    lanes.len() - 1
                });
                let color = alloc_lane_color();
                lanes[idx] = Some(Lane {
                    target: hash.clone(),
                    color,
                    pending_close: false,
                    converge_to: None,
                });
                idx
            }
        };

        let my_color = lanes[my_lane_idx].as_ref().unwrap().color;

        // Collect extra merge parent lanes (for merge commits)
        let mut extra_parent_info: Vec<(usize, u8)> = Vec::new(); // (lane_idx, color)

        // Update lanes for parent tracking
        if parents.is_empty() {
            // Root commit - this lane closes
            lanes[my_lane_idx] = None;
        } else {
            let first_parent = &parents[0];

            // Check if first parent already has a lane
            let first_parent_existing = lanes.iter().enumerate()
                .filter(|(i, _)| *i != my_lane_idx)
                .find(|(_, l)| l.as_ref().map(|l| l.target == *first_parent && !l.pending_close).unwrap_or(false))
                .map(|(i, _)| i);

            if let Some(existing_idx) = first_parent_existing {
                // First parent already targeted by another lane - mark current as pending close
                let color = my_color;
                lanes[my_lane_idx] = Some(Lane {
                    target: first_parent.clone(),
                    color,
                    pending_close: true,
                    converge_to: Some(existing_idx),
                });
            } else {
                // Update current lane to target first parent
                let color = my_color;
                lanes[my_lane_idx] = Some(Lane {
                    target: first_parent.clone(),
                    color,
                    pending_close: false,
                    converge_to: None,
                });
            }

            // Handle additional parents (merge commits)
            for parent in parents.iter().skip(1) {
                let existing = lanes.iter().position(|l| {
                    l.as_ref().map(|l| l.target == *parent && !l.pending_close).unwrap_or(false)
                });

                if let Some(existing_idx) = existing {
                    let c = lanes[existing_idx].as_ref().unwrap().color;
                    extra_parent_info.push((existing_idx, c));
                } else {
                    // Create new lane for this parent
                    let new_idx = lanes.iter().position(|l| l.is_none()).unwrap_or_else(|| {
                        lanes.push(None);
                        lanes.len() - 1
                    });
                    let new_color = alloc_lane_color();
                    lanes[new_idx] = Some(Lane {
                        target: parent.clone(),
                        color: new_color,
                        pending_close: false,
                        converge_to: None,
                    });
                    extra_parent_info.push((new_idx, new_color));
                }
            }
        }

        // Build the graph row for this commit
        let graph_row = build_commit_row(
            &lanes, 
            commit,
            my_lane_idx,
            my_color,
            &extra_parent_info,
        );

        let branch_list = branches.get(hash).cloned().unwrap_or_default();

        result.push(DisplayRow::Commit(CommitRow {
            commit: commit.clone(),
            graph: graph_row,
            branches: branch_list,
            selected_branch_idx: 0,
        }));

        // Check if we need to draw connector row AFTER this commit
        // (when the current commit caused some lanes to become pending-close and now 
        // we should check if all remaining lanes target the same thing - but this is
        // handled at the START of the next iteration)
    }

    result
}

