use anyhow::{Context, Result};
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use std::collections::HashMap;
use std::time::{Duration, Instant};

use crate::config::Config;
use crate::git::{CommitDetail, CommitInfo, BranchInfo, GitRepo};
use crate::graph::{build_display_rows, DisplayRow, CommitRow};
use crate::tui::Tui;
use crate::ui;

/// Application mode
#[derive(Debug, Clone, PartialEq)]
pub enum AppMode {
    Normal,
    Help,
    Search,
    NewBranch,
    ConfirmDelete,
    ConfirmCheckout,
    BranchesPopup,  // showing branches popup on multi-branch commit
    FetchInProgress,
    Message(String),  // showing a message
}

/// Uncommitted changes pseudo-commit
pub struct UncommittedChanges {
    pub file_count: usize,
    pub files: Vec<crate::git::FileChange>,
    pub total_additions: usize,
    pub total_deletions: usize,
}

pub struct App {
    pub repo: GitRepo,
    pub config: Config,

    // Display rows (commits + connectors)
    pub display_rows: Vec<DisplayRow>,

    // Navigation
    pub selected_idx: usize,  // index into commit list (not display rows)
    pub scroll_offset: usize,  // top of visible window (in display rows)

    // Commit list derived from display_rows
    pub commit_indices: Vec<usize>,  // indices into display_rows for commit rows

    // Current commit detail
    pub current_detail: Option<CommitDetail>,

    // Uncommitted changes (shown as first item if present)
    pub uncommitted: Option<UncommittedChanges>,

    // Branch info
    pub repo_name: String,
    pub current_branch: String,

    // Mode
    pub mode: AppMode,

    // Search
    pub search_query: String,
    pub search_results: Vec<BranchSearchResult>,
    pub search_selected: usize,

    // New branch name input
    pub new_branch_name: String,

    // Branch to delete
    pub branch_to_delete: Option<String>,

    // Refresh tracking
    pub last_refresh: Instant,
    pub last_fetch: Instant,

    // Status message
    pub status_message: Option<(String, Instant)>,
}

#[derive(Debug, Clone)]
pub struct BranchSearchResult {
    pub name: String,
    pub commit_hash: String,
    pub score: i64,
}

impl App {
    pub fn new(repo: GitRepo, config: Config) -> Result<Self> {
        let repo_name = repo.repo_name();
        let current_branch = repo.current_branch();

        let mut app = App {
            repo,
            config,
            display_rows: Vec::new(),
            selected_idx: 0,
            scroll_offset: 0,
            commit_indices: Vec::new(),
            current_detail: None,
            uncommitted: None,
            repo_name,
            current_branch,
            mode: AppMode::Normal,
            search_query: String::new(),
            search_results: Vec::new(),
            search_selected: 0,
            new_branch_name: String::new(),
            branch_to_delete: None,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            status_message: None,
        };

        app.refresh()?;
        Ok(app)
    }

    pub fn refresh(&mut self) -> Result<()> {
        self.current_branch = self.repo.current_branch();

        // Get branches
        let branches_list = self.repo.get_branches()?;
        let mut branches_map: HashMap<String, Vec<BranchInfo>> = HashMap::new();
        for branch in &branches_list {
            branches_map.entry(branch.commit_hash.clone())
                .or_default()
                .push(branch.clone());
        }

        // Get commits (max 500)
        let commits = self.repo.get_commits(500)?;

        // Build graph
        let display_rows = build_display_rows(&commits, &branches_map);

        // Build commit indices
        let mut commit_indices = Vec::new();
        for (i, row) in display_rows.iter().enumerate() {
            if let DisplayRow::Commit(_) = row {
                commit_indices.push(i);
            }
        }

        self.display_rows = display_rows;
        self.commit_indices = commit_indices;

        // Check for uncommitted changes
        if self.repo.has_uncommitted_changes() {
            let (files, additions, deletions) = self.repo.get_uncommitted_diff()?;
            let file_count = files.len();
            self.uncommitted = Some(UncommittedChanges {
                file_count,
                files,
                total_additions: additions,
                total_deletions: deletions,
            });
        } else {
            self.uncommitted = None;
        }

        // Update current detail
        self.update_detail()?;

        self.last_refresh = Instant::now();
        Ok(())
    }

    fn update_detail(&mut self) -> Result<()> {
        let n_commits = self.commit_count();
        if n_commits == 0 {
            self.current_detail = None;
            return Ok(());
        }

        // selected_idx: 0 = first "commit" position
        // If uncommitted changes exist, idx 0 is uncommitted, idx 1+ are commits
        let has_uncommitted = self.uncommitted.is_some();

        if has_uncommitted && self.selected_idx == 0 {
            // Showing uncommitted changes detail
            self.current_detail = None;
            return Ok(());
        }

        let commit_idx = if has_uncommitted {
            self.selected_idx - 1
        } else {
            self.selected_idx
        };

        if commit_idx < self.commit_indices.len() {
            let display_idx = self.commit_indices[commit_idx];
            if let DisplayRow::Commit(cr) = &self.display_rows[display_idx] {
                let hash = cr.commit.hash.clone();
                match self.repo.get_commit_detail(&hash) {
                    Ok(detail) => self.current_detail = Some(detail),
                    Err(_) => self.current_detail = None,
                }
            }
        }
        Ok(())
    }

    pub fn commit_count(&self) -> usize {
        let base = self.commit_indices.len();
        let extra = if self.uncommitted.is_some() { 1 } else { 0 };
        base + extra
    }

    pub fn get_current_commit_row(&self) -> Option<&CommitRow> {
        let has_uncommitted = self.uncommitted.is_some();
        let commit_idx = if has_uncommitted {
            if self.selected_idx == 0 { return None; }
            self.selected_idx - 1
        } else {
            self.selected_idx
        };

        if commit_idx < self.commit_indices.len() {
            let display_idx = self.commit_indices[commit_idx];
            if let DisplayRow::Commit(cr) = &self.display_rows[display_idx] {
                return Some(cr);
            }
        }
        None
    }

    pub fn move_down(&mut self) {
        let count = self.commit_count();
        if count == 0 { return; }
        if self.selected_idx < count - 1 {
            self.selected_idx += 1;
            let _ = self.update_detail();
        }
    }

    pub fn move_up(&mut self) {
        if self.selected_idx > 0 {
            self.selected_idx -= 1;
            let _ = self.update_detail();
        }
    }

    pub fn move_to_top(&mut self) {
        self.selected_idx = 0;
        self.scroll_offset = 0;
        let _ = self.update_detail();
    }

    pub fn move_to_bottom(&mut self) {
        let count = self.commit_count();
        if count > 0 {
            self.selected_idx = count - 1;
            let _ = self.update_detail();
        }
    }

    pub fn page_down(&mut self, page_size: usize) {
        let count = self.commit_count();
        if count == 0 { return; }
        let new_idx = (self.selected_idx + page_size).min(count - 1);
        self.selected_idx = new_idx;
        let _ = self.update_detail();
    }

    pub fn page_up(&mut self, page_size: usize) {
        self.selected_idx = self.selected_idx.saturating_sub(page_size);
        let _ = self.update_detail();
    }

    pub fn jump_to_next_branch(&mut self) {
        let has_uncommitted = self.uncommitted.is_some();
        let start_commit_idx = if has_uncommitted {
            if self.selected_idx == 0 { 0 }
            else { self.selected_idx - 1 + 1 } // next commit after current
        } else {
            self.selected_idx + 1
        };

        for i in start_commit_idx..self.commit_indices.len() {
            let display_idx = self.commit_indices[i];
            if let DisplayRow::Commit(cr) = &self.display_rows[display_idx] {
                if !cr.branches.is_empty() {
                    self.selected_idx = i + if has_uncommitted { 1 } else { 0 };
                    let _ = self.update_detail();
                    return;
                }
            }
        }
    }

    pub fn jump_to_prev_branch(&mut self) {
        let has_uncommitted = self.uncommitted.is_some();
        let current_commit_idx = if has_uncommitted {
            if self.selected_idx == 0 { return; }
            self.selected_idx - 1
        } else {
            self.selected_idx
        };

        if current_commit_idx == 0 { return; }

        for i in (0..current_commit_idx).rev() {
            let display_idx = self.commit_indices[i];
            if let DisplayRow::Commit(cr) = &self.display_rows[display_idx] {
                if !cr.branches.is_empty() {
                    self.selected_idx = i + if has_uncommitted { 1 } else { 0 };
                    let _ = self.update_detail();
                    return;
                }
            }
        }
    }

    pub fn jump_to_head(&mut self) {
        let has_uncommitted = self.uncommitted.is_some();

        for (i, display_idx) in self.commit_indices.iter().enumerate() {
            if let DisplayRow::Commit(cr) = &self.display_rows[*display_idx] {
                if cr.commit.is_head {
                    self.selected_idx = i + if has_uncommitted { 1 } else { 0 };
                    let _ = self.update_detail();
                    return;
                }
            }
        }
    }

    pub fn select_left_branch(&mut self) {
        if let Some(cr) = self.get_current_commit_row_mut() {
            if cr.branches.len() > 1 {
                if cr.selected_branch_idx > 0 {
                    cr.selected_branch_idx -= 1;
                } else {
                    cr.selected_branch_idx = cr.branches.len() - 1;
                }
            }
        }
    }

    pub fn select_right_branch(&mut self) {
        if let Some(cr) = self.get_current_commit_row_mut() {
            if cr.branches.len() > 1 {
                cr.selected_branch_idx = (cr.selected_branch_idx + 1) % cr.branches.len();
            }
        }
    }

    fn get_current_commit_row_mut(&mut self) -> Option<&mut CommitRow> {
        let has_uncommitted = self.uncommitted.is_some();
        let commit_idx = if has_uncommitted {
            if self.selected_idx == 0 { return None; }
            self.selected_idx - 1
        } else {
            self.selected_idx
        };

        if commit_idx < self.commit_indices.len() {
            let display_idx = self.commit_indices[commit_idx];
            if let DisplayRow::Commit(cr) = &mut self.display_rows[display_idx] {
                return Some(cr);
            }
        }
        None
    }

    pub fn get_selected_branch_name(&self) -> Option<String> {
        self.get_current_commit_row().and_then(|cr| {
            if cr.branches.is_empty() {
                None
            } else {
                let idx = cr.selected_branch_idx.min(cr.branches.len() - 1);
                Some(cr.branches[idx].name.clone())
            }
        })
    }

    pub fn get_selected_commit_hash(&self) -> Option<String> {
        self.get_current_commit_row().map(|cr| cr.commit.hash.clone())
    }

    pub fn checkout_selected(&mut self) -> Result<String> {
        // If selected branch, checkout that branch
        // Otherwise checkout the commit hash (detached HEAD)
        let target = if let Some(branch) = self.get_selected_branch_name() {
            branch
        } else if let Some(hash) = self.get_selected_commit_hash() {
            hash
        } else {
            return Ok("Nothing to checkout".to_string());
        };

        let msg = self.repo.checkout(&target)?;
        self.refresh()?;
        Ok(msg)
    }

    pub fn start_new_branch(&mut self) {
        self.new_branch_name.clear();
        self.mode = AppMode::NewBranch;
    }

    pub fn create_branch(&mut self) -> Result<String> {
        let name = self.new_branch_name.clone();
        if name.is_empty() {
            return Ok("Branch name is empty".to_string());
        }
        let hash = self.get_selected_commit_hash()
            .ok_or_else(|| anyhow::anyhow!("No commit selected"))?;
        let msg = self.repo.create_branch(&name, &hash)?;
        self.refresh()?;
        Ok(msg)
    }

    pub fn start_delete_branch(&mut self) {
        if let Some(branch_name) = self.get_selected_branch_name() {
            // Can't delete HEAD branch
            if branch_name == self.current_branch {
                self.set_status_message("Cannot delete current branch".to_string());
                return;
            }
            // Can't delete remote branches
            if let Some(cr) = self.get_current_commit_row() {
                if let Some(branch) = cr.branches.iter().find(|b| b.name == branch_name) {
                    if branch.is_remote {
                        self.set_status_message("Cannot delete remote branches".to_string());
                        return;
                    }
                }
            }
            self.branch_to_delete = Some(branch_name);
            self.mode = AppMode::ConfirmDelete;
        }
    }

    pub fn delete_branch(&mut self) -> Result<String> {
        let name = self.branch_to_delete.clone()
            .ok_or_else(|| anyhow::anyhow!("No branch to delete"))?;
        let msg = self.repo.delete_branch(&name)?;
        self.refresh()?;
        Ok(msg)
    }

    pub fn fetch(&mut self) -> Result<String> {
        let msg = self.repo.fetch()?;
        self.refresh()?;
        self.last_fetch = Instant::now();
        Ok(msg)
    }

    pub fn update_search(&mut self) {
        let query = &self.search_query;
        let branches = self.get_all_branches();

        if query.is_empty() {
            self.search_results = Vec::new();
            return;
        }

        use fuzzy_matcher::FuzzyMatcher;
        use fuzzy_matcher::skim::SkimMatcherV2;
        let matcher = SkimMatcherV2::default();

        let mut results: Vec<BranchSearchResult> = branches.into_iter()
            .filter_map(|(name, hash)| {
                matcher.fuzzy_match(&name, query).map(|score| {
                    BranchSearchResult { name, commit_hash: hash, score }
                })
            })
            .collect();

        results.sort_by(|a, b| b.score.cmp(&a.score).then(a.name.cmp(&b.name)));

        self.search_results = results;
        self.search_selected = 0;
    }

    fn get_all_branches(&self) -> Vec<(String, String)> {
        let mut branches = Vec::new();
        for display_idx in &self.commit_indices {
            if let DisplayRow::Commit(cr) = &self.display_rows[*display_idx] {
                for branch in &cr.branches {
                    branches.push((branch.name.clone(), cr.commit.hash.clone()));
                }
            }
        }
        branches
    }

    pub fn jump_to_branch(&mut self, branch_name: &str) {
        let has_uncommitted = self.uncommitted.is_some();

        for (i, display_idx) in self.commit_indices.iter().enumerate() {
            if let DisplayRow::Commit(cr) = &self.display_rows[*display_idx] {
                if cr.branches.iter().any(|b| b.name == branch_name) {
                    self.selected_idx = i + if has_uncommitted { 1 } else { 0 };
                    // Also set the selected branch
                    if let Some(branch_idx) = cr.branches.iter().position(|b| b.name == branch_name) {
                        // We need to update the CommitRow's selected_branch_idx
                        // We'll need mutable access
                    }
                    let _ = self.update_detail();
                    return;
                }
            }
        }
    }

    pub fn jump_to_branch_and_select(&mut self, branch_name: &str) {
        let has_uncommitted = self.uncommitted.is_some();
        let mut target_idx = None;
        let mut branch_idx_in_commit = 0;

        for (i, display_idx) in self.commit_indices.iter().enumerate() {
            if let DisplayRow::Commit(cr) = &self.display_rows[*display_idx] {
                if let Some(bi) = cr.branches.iter().position(|b| b.name == branch_name) {
                    target_idx = Some(i + if has_uncommitted { 1 } else { 0 });
                    branch_idx_in_commit = bi;
                    break;
                }
            }
        }

        if let Some(idx) = target_idx {
            self.selected_idx = idx;
            // Set the selected branch in the commit row
            if let Some(cr) = self.get_current_commit_row_mut() {
                cr.selected_branch_idx = branch_idx_in_commit;
            }
            let _ = self.update_detail();
        }
    }

    pub fn set_status_message(&mut self, msg: String) {
        self.status_message = Some((msg, Instant::now()));
    }

    pub fn clear_expired_status(&mut self) {
        if let Some((_, time)) = &self.status_message {
            if time.elapsed() > Duration::from_secs(3) {
                self.status_message = None;
            }
        }
    }
}

pub fn run(terminal: &mut Tui, config: Config) -> Result<()> {
    let repo = GitRepo::open()
        .context("Git repository not found. Please run inside a Git repository.")?;

    let mut app = App::new(repo, config)?;

    loop {
        // Calculate visible area height from terminal
        let term_size = terminal.size()?;
        let list_height = (term_size.height as usize).saturating_sub(20).max(5);
        let page_size = list_height / 2;

        // Update scroll to keep selected visible
        update_scroll(&mut app, list_height);

        // Clear expired status messages
        app.clear_expired_status();

        // Check auto-refresh
        if app.config.auto_refresh() && app.last_refresh.elapsed() >= Duration::from_secs(app.config.refresh_interval()) {
            let _ = app.refresh();
        }

        if app.config.auto_fetch() && app.last_fetch.elapsed() >= Duration::from_secs(app.config.fetch_interval()) {
            let _ = app.repo.fetch();
            let _ = app.refresh();
            app.last_fetch = Instant::now();
        }

        // Draw
        terminal.draw(|f| {
            ui::draw(f, &app);
        })?;

        // Handle events with timeout
        if !event::poll(Duration::from_millis(250))? {
            continue;
        }

        match event::read()? {
            Event::Key(key) => {
                if handle_key(&mut app, key, page_size)? {
                    return Ok(());
                }
            }
            Event::Resize(_, _) => {
                // Terminal resized, redraw
            }
            _ => {}
        }
    }
}

fn update_scroll(app: &mut App, list_height: usize) {
    // Calculate the display row index for the selected commit
    let has_uncommitted = app.uncommitted.is_some();

    let selected_display_idx = if has_uncommitted && app.selected_idx == 0 {
        0 // Uncommitted changes is always first
    } else {
        let commit_idx = if has_uncommitted {
            app.selected_idx.saturating_sub(1)
        } else {
            app.selected_idx
        };

        if commit_idx < app.commit_indices.len() {
            app.commit_indices[commit_idx] + if has_uncommitted { 1 } else { 0 }
        } else {
            0
        }
    };

    // Total display rows
    let total_display = app.display_rows.len() + if has_uncommitted { 1 } else { 0 };

    // Ensure selected is visible
    if selected_display_idx < app.scroll_offset {
        app.scroll_offset = selected_display_idx;
    } else if selected_display_idx >= app.scroll_offset + list_height {
        app.scroll_offset = selected_display_idx.saturating_sub(list_height - 1);
    }
}

fn handle_key(app: &mut App, key: KeyEvent, page_size: usize) -> Result<bool> {
    match &app.mode.clone() {
        AppMode::Normal => handle_normal_key(app, key, page_size),
        AppMode::Help => handle_help_key(app, key),
        AppMode::Search => handle_search_key(app, key),
        AppMode::NewBranch => handle_new_branch_key(app, key),
        AppMode::ConfirmDelete => handle_confirm_delete_key(app, key),
        AppMode::Message(msg) => {
            let msg = msg.clone();
            match key.code {
                KeyCode::Esc | KeyCode::Enter | KeyCode::Char('q') => {
                    app.mode = AppMode::Normal;
                }
                _ => {}
            }
            Ok(false)
        }
        _ => Ok(false),
    }
}

fn handle_normal_key(app: &mut App, key: KeyEvent, page_size: usize) -> Result<bool> {
    match key.code {
        // Quit
        KeyCode::Char('q') | KeyCode::Esc => {
            return Ok(true);
        }

        // Navigation
        KeyCode::Char('j') | KeyCode::Down => {
            app.move_down();
        }
        KeyCode::Char('k') | KeyCode::Up => {
            app.move_up();
        }
        KeyCode::Char('g') | KeyCode::Home => {
            app.move_to_top();
        }
        KeyCode::Char('G') | KeyCode::End => {
            app.move_to_bottom();
        }
        KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            app.page_down(page_size);
        }
        KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            app.page_up(page_size);
        }

        // Branch navigation
        KeyCode::Char(']') | KeyCode::Tab => {
            app.jump_to_next_branch();
        }
        KeyCode::Char('[') | KeyCode::BackTab => {
            app.jump_to_prev_branch();
        }
        KeyCode::Char('@') => {
            app.jump_to_head();
        }

        // h/l for same-commit branch selection
        KeyCode::Char('h') | KeyCode::Left => {
            app.select_left_branch();
        }
        KeyCode::Char('l') | KeyCode::Right => {
            app.select_right_branch();
        }

        // Help
        KeyCode::Char('?') => {
            app.mode = AppMode::Help;
        }

        // Search
        KeyCode::Char('/') => {
            app.search_query.clear();
            app.search_results.clear();
            app.search_selected = 0;
            app.mode = AppMode::Search;
        }

        // Git operations
        KeyCode::Enter => {
            match app.checkout_selected() {
                Ok(msg) => {
                    app.set_status_message(msg);
                }
                Err(e) => {
                    app.set_status_message(format!("Error: {}", e));
                }
            }
        }

        KeyCode::Char('b') => {
            app.start_new_branch();
        }

        KeyCode::Char('d') => {
            app.start_delete_branch();
        }

        KeyCode::Char('f') => {
            match app.fetch() {
                Ok(msg) => {
                    app.set_status_message(msg);
                }
                Err(e) => {
                    app.set_status_message(format!("Error: {}", e));
                }
            }
        }

        KeyCode::Char('R') => {
            match app.refresh() {
                Ok(_) => {}
                Err(e) => {
                    app.set_status_message(format!("Error: {}", e));
                }
            }
        }

        _ => {}
    }

    Ok(false)
}

fn handle_help_key(app: &mut App, key: KeyEvent) -> Result<bool> {
    match key.code {
        KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('?') => {
            app.mode = AppMode::Normal;
        }
        _ => {}
    }
    Ok(false)
}

fn handle_search_key(app: &mut App, key: KeyEvent) -> Result<bool> {
    match key.code {
        KeyCode::Esc => {
            app.mode = AppMode::Normal;
            app.search_query.clear();
            app.search_results.clear();
        }
        KeyCode::Backspace => {
            if app.search_query.is_empty() {
                app.mode = AppMode::Normal;
            } else {
                app.search_query.pop();
                app.update_search();
            }
        }
        KeyCode::Enter => {
            if let Some(result) = app.search_results.get(app.search_selected) {
                let branch_name = result.name.clone();
                app.mode = AppMode::Normal;
                app.search_query.clear();
                app.search_results.clear();
                app.jump_to_branch_and_select(&branch_name);
            } else {
                app.mode = AppMode::Normal;
                app.search_query.clear();
            }
        }
        KeyCode::Up | KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            if app.search_selected > 0 {
                app.search_selected -= 1;
            }
        }
        KeyCode::Down | KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            if app.search_selected + 1 < app.search_results.len() {
                app.search_selected += 1;
            }
        }
        // Handle Ctrl+k and Ctrl+j
        KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            if app.search_selected > 0 {
                app.search_selected -= 1;
            }
        }
        KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            if app.search_selected + 1 < app.search_results.len() {
                app.search_selected += 1;
            }
        }
        KeyCode::Char(c) => {
            app.search_query.push(c);
            app.update_search();
        }
        _ => {}
    }
    Ok(false)
}

fn handle_new_branch_key(app: &mut App, key: KeyEvent) -> Result<bool> {
    match key.code {
        KeyCode::Esc => {
            app.mode = AppMode::Normal;
            app.new_branch_name.clear();
        }
        KeyCode::Backspace => {
            app.new_branch_name.pop();
        }
        KeyCode::Enter => {
            if !app.new_branch_name.is_empty() {
                match app.create_branch() {
                    Ok(msg) => {
                        app.mode = AppMode::Normal;
                        app.new_branch_name.clear();
                        app.set_status_message(msg);
                    }
                    Err(e) => {
                        app.mode = AppMode::Normal;
                        app.new_branch_name.clear();
                        app.set_status_message(format!("Error: {}", e));
                    }
                }
            } else {
                app.mode = AppMode::Normal;
            }
        }
        KeyCode::Char(c) => {
            app.new_branch_name.push(c);
        }
        _ => {}
    }
    Ok(false)
}

fn handle_confirm_delete_key(app: &mut App, key: KeyEvent) -> Result<bool> {
    match key.code {
        KeyCode::Char('y') | KeyCode::Char('Y') => {
            match app.delete_branch() {
                Ok(msg) => {
                    app.mode = AppMode::Normal;
                    app.branch_to_delete = None;
                    app.set_status_message(msg);
                }
                Err(e) => {
                    app.mode = AppMode::Normal;
                    app.branch_to_delete = None;
                    app.set_status_message(format!("Error: {}", e));
                }
            }
        }
        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
            app.mode = AppMode::Normal;
            app.branch_to_delete = None;
        }
        _ => {}
    }
    Ok(false)
}
