fn draw_branches_popup(f: &mut Frame, app: &App, cr: &crate::graph::CommitRow, list_area: Rect) {
    // Find position of selected commit in display
    let has_uncommitted = app.uncommitted.is_some();
    let commit_display_idx = if has_uncommitted && app.selected_idx == 0 {
        return;
    } else {
        let commit_idx = if has_uncommitted { app.selected_idx - 1 } else { app.selected_idx };
        if commit_idx < app.commit_indices.len() {
            app.commit_indices[commit_idx]
        } else {
            return;
        }
    };

    let row_y_in_list = (commit_display_idx + if has_uncommitted { 1 } else { 0 })
        .saturating_sub(app.scroll_offset);

    // Position the popup to the right of the commit entry
    let popup_width = cr.branches.iter().map(|b| b.name.len()).max().unwrap_or(5) as u16 + 4;
    let popup_height = cr.branches.len() as u16 + 2;

    // Calculate position - right side, near the commit row
    let popup_x = list_area.x + list_area.width.saturating_sub(popup_width + 5);
    let popup_y = list_area.y + 1 + row_y_in_list as u16;

    let popup_area = Rect {
        x: popup_x.min(list_area.x + list_area.width.saturating_sub(popup_width)),
        y: popup_y.min(list_area.y + list_area.height.saturating_sub(popup_height)),
        width: popup_width.min(list_area.width),
        height: popup_height.min(list_area.height),
    };

    f.render_widget(Clear, popup_area);

    let block = Block::default()
        .title(" Branches ")
        .borders(Borders::ALL);

    let inner = block.inner(popup_area);
    f.render_widget(block, popup_area);

    let selected_idx = cr.selected_branch_idx.min(cr.branches.len() - 1);

    for (i, branch) in cr.branches.iter().enumerate() {
        if i < inner.height as usize {
            let is_selected = i == selected_idx;
            let prefix = if is_selected { "▶ " } else { "  " };
            let line = Line::from(vec![
                Span::styled(
                    format!("{}{}", prefix, branch.name),
                    if is_selected { Style::default().add_modifier(Modifier::BOLD) } else { Style::default() }
                ),
            ]);
            let line_area = Rect {
                x: inner.x,
                y: inner.y + i as u16,
                width: inner.width,
                height: 1,
            };
            f.render_widget(Paragraph::new(line), line_area);
        }
    }
