use crate::app::{App, AppMode, UncommittedChanges};
use crate::graph::{DisplayRow, GraphCell, LANE_COLORS};

const GRAPH_BOLD: bool = true;

fn lane_to_color(color_idx: u8) -> Color {
    Color::Indexed(color_idx)
}

fn branch_label_color(color_idx: u8) -> Style {
    Style::default()
        .fg(lane_to_color(color_idx))
