fn draw_search_overlay(f: &mut Frame, app: &App, area: Rect) {
    let overlay_width = (area.width as usize * 60 / 100) as u16;
    let overlay_width = overlay_width.max(50).min(area.width);

    let has_results = !app.search_results.is_empty();
    let results_height = if has_results { (app.search_results.len().min(10) + 1) as u16 } else { 1 };
    let overlay_height = 3 + results_height + 1; // title + input + divider + results + hint

    let x = (area.width.saturating_sub(overlay_width)) / 2;
    let y = (area.height.saturating_sub(overlay_height + 10)) / 2 + 10;

    let overlay_area = Rect {
        x: area.x + x,
        y: area.y + y,
        width: overlay_width,
        height: (overlay_height + 4).min(area.height - y),
    };

    f.render_widget(Clear, overlay_area);

    let block = Block::default()
        .title(" Search branches ")
        .borders(Borders::ALL);

    let inner = block.inner(overlay_area);
    f.render_widget(block, overlay_area);

    // Input line with cursor
    let input_text = format!("  {}_{}", app.search_query, " ".repeat(30));
    let input_line = Line::from(vec![
        Span::raw(format!("  {}_", app.search_query)),
    ]);

    let input_area = Rect {
        x: inner.x,
        y: inner.y,
        width: inner.width,
        height: 1,
    };
    f.render_widget(Paragraph::new(input_line), input_area);

    if !has_results {
        // Show hint
        let hint = if app.search_query.is_empty() {
            "  Enter: confirm  Esc: cancel"
        } else {
            "  No matches"
        };
        let hint_area = Rect {
            x: inner.x,
            y: inner.y + 1,
            width: inner.width,
            height: 1,
        };
        f.render_widget(Paragraph::new(hint.to_string()), hint_area);
    } else {
        // Divider
        let divider_area = Rect {
            x: inner.x,
            y: inner.y + 1,
            width: inner.width,
            height: 1,
        };
        let divider = "─".repeat(inner.width as usize);
        f.render_widget(Paragraph::new(divider), divider_area);

        // Results
        for (i, result) in app.search_results.iter().take(10).enumerate() {
            let is_selected = i == app.search_selected;
            let prefix = if is_selected { "▶ " } else { "  " };
            let line = Line::from(vec![
                Span::styled(
                    format!("{}{}", prefix, result.name),
                    if is_selected { Style::default().add_modifier(Modifier::BOLD) } else { Style::default() }
                ),
            ]);
            let result_area = Rect {
                x: inner.x,
                y: inner.y + 2 + i as u16,
                width: inner.width,
                height: 1,
            };
            f.render_widget(Paragraph::new(line), result_area);
        }

        // Hint at bottom
        let hint_y = inner.y + 2 + app.search_results.len().min(10) as u16;
        if hint_y < inner.y + inner.height {
            let hint_area = Rect {
                x: inner.x,
                y: hint_y,
                width: inner.width,
                height: 1,
            };
            f.render_widget(Paragraph::new("  ↑↓: select  Enter: jump  Esc: cancel"), hint_area);
        }
    }
}

