use ratatui::{
    Frame,
    layout::{Constraint, Direction, Layout, Rect, Alignment},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, BorderType, Clear, Paragraph, Widget},
};

use crate::app::{App, AppMode, UncommittedChanges};
use crate::graph::{DisplayRow, GraphCell, LANE_COLORS};

const GRAPH_BOLD: bool = true;

fn lane_to_color(color_idx: u8) -> Color {
    Color::Indexed(color_idx)
}

fn branch_label_color(color_idx: u8) -> Style {
    Style::default()
        .fg(lane_to_color(color_idx))
        .add_modifier(Modifier::BOLD)
}

pub fn draw(f: &mut Frame, app: &App) {
    let size = f.area();

    // Layout: main area (top) + bottom status bar
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Fill(1),
            Constraint::Length(1),
        ])
        .split(size);

    let main_area = chunks[0];
    let status_area = chunks[1];

    // Split main into top (commits) and bottom (details)
    let detail_height = 15u16;
    let list_height = main_area.height.saturating_sub(detail_height);
    let list_height = list_height.max(3);

    let top_bottom = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(list_height),
            Constraint::Length(detail_height),
        ])
        .split(main_area);

    let list_area = top_bottom[0];
    let detail_area = top_bottom[1];

    // Split detail into left (commit info) and right (file changes)
    let detail_split = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(50),
            Constraint::Percentage(50),
        ])
        .split(detail_area);

    let commit_detail_area = detail_split[0];
    let files_detail_area = detail_split[1];

    // Draw panels
    draw_commit_list(f, app, list_area);
    draw_commit_detail(f, app, commit_detail_area);
    draw_file_changes(f, app, files_detail_area);
    draw_status_bar(f, app, status_area);

    // Draw overlays
    match &app.mode {
        AppMode::Help => {
            draw_help_overlay(f, size);
        }
        AppMode::Search => {
            draw_search_overlay(f, app, size);
        }
        AppMode::NewBranch => {
            draw_new_branch_overlay(f, app, size);
        }
        AppMode::ConfirmDelete => {
            draw_confirm_delete_overlay(f, app, size);
        }
        _ => {}
    }

    // Draw branches popup if current row has multiple branches
    if app.mode == AppMode::Normal || app.mode == AppMode::Help {
        if let Some(cr) = app.get_current_commit_row() {
            if cr.branches.len() > 1 {
                draw_branches_popup(f, app, cr, list_area);
            }
        }
    }
}

fn draw_commit_list(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title(" Commits ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Indexed(8)));

    let inner = block.inner(area);
    f.render_widget(block, area);

    let inner_width = inner.width as usize;
    let visible_height = inner.height as usize;

    // Build list of all display items (uncommitted + display rows)
    // Each item in the "virtual list" is either:
    // - Uncommitted changes (if present)
    // - A DisplayRow (commit or connector)

    let has_uncommitted = app.uncommitted.is_some();

    // Total number of virtual rows = (1 if uncommitted) + display_rows.len()
    let total_virtual_rows = (if has_uncommitted { 1 } else { 0 }) + app.display_rows.len();

    // Scroll offset
    let scroll = app.scroll_offset;

    let mut y = 0usize;
    let mut virtual_idx = 0usize;

    // Uncommitted changes row
    if has_uncommitted {
        if virtual_idx >= scroll && y < visible_height {
            let is_selected = app.selected_idx == 0;
            if let Some(uncommitted) = &app.uncommitted {
                let row = build_uncommitted_row(uncommitted, inner_width, is_selected);
                let area = Rect {
                    x: inner.x,
                    y: inner.y + y as u16,
                    width: inner.width,
                    height: 1,
                };
                f.render_widget(row, area);
                y += 1;
            }
        }
        virtual_idx += 1;
    }

    // Display rows
    for (di, display_row) in app.display_rows.iter().enumerate() {
        if virtual_idx >= scroll + visible_height {
            break;
        }

        if virtual_idx >= scroll {
            let row_y = inner.y + y as u16;

            match display_row {
                DisplayRow::Commit(cr) => {
                    // Find if this commit is selected
                    let commit_idx_in_list = app.commit_indices.iter().position(|&di2| di2 == di);
                    let is_selected = commit_idx_in_list.map(|ci| {
                        let adjusted = ci + if has_uncommitted { 1 } else { 0 };
                        adjusted == app.selected_idx
                    }).unwrap_or(false);

                    let row_widget = build_commit_row_widget(cr, inner_width, is_selected);
                    let row_area = Rect {
                        x: inner.x,
                        y: row_y,
                        width: inner.width,
                        height: 1,
                    };
                    f.render_widget(row_widget, row_area);
                }
                DisplayRow::Connector(connector) => {
                    let row_widget = build_connector_row_widget(&connector.graph.cells, inner_width);
                    let row_area = Rect {
                        x: inner.x,
                        y: row_y,
                        width: inner.width,
                        height: 1,
                    };
                    f.render_widget(row_widget, row_area);
                }
            }

            y += 1;
        }

        virtual_idx += 1;
    }
}

fn build_uncommitted_row(uncommitted: &UncommittedChanges, width: usize, selected: bool) -> Paragraph<'static> {
    let node_style = Style::default()
        .fg(Color::Indexed(12))
        .add_modifier(Modifier::BOLD);

    let node_span = Span::styled("●", node_style);
    let space_span = Span::raw("    ");
    let msg_span = Span::styled(
        format!("uncommitted changes ({})", uncommitted.file_count),
        Style::default()
    );

    let spans: Vec<Span> = vec![node_span, space_span, msg_span];
    let line = Line::from(spans);

    let style = if selected {
        Style::default().bg(Color::Indexed(8))
    } else {
        Style::default()
    };

    Paragraph::new(line).style(style)
}

fn build_commit_row_widget(cr: &crate::graph::CommitRow, width: usize, selected: bool) -> Paragraph<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();

    // Build graph portion
    let graph_bold = Style::default().add_modifier(Modifier::BOLD);

    let mut graph_spans = build_graph_spans(&cr.graph.cells);
    spans.append(&mut graph_spans);

    // Space after graph
    spans.push(Span::raw("  "));

    // Branch labels
    let selected_branch_idx = cr.selected_branch_idx.min(cr.branches.len().saturating_sub(1));
    let local_branches: Vec<&crate::git::BranchInfo> = cr.branches.iter()
        .filter(|b| !b.is_remote)
        .collect();
    let remote_branches: Vec<&crate::git::BranchInfo> = cr.branches.iter()
        .filter(|b| b.is_remote)
        .collect();

    // Show the selected branch label
    if !cr.branches.is_empty() {
        let selected_branch = &cr.branches[selected_branch_idx];
        let branch_name = &selected_branch.name;

        // Get color based on lane
        let label_color = get_branch_label_color(cr, selected_branch_idx);

        let label_style = Style::default()
            .fg(label_color)
            .add_modifier(Modifier::BOLD);

        let extra_count = cr.branches.len().saturating_sub(1);
        let label_text = if extra_count > 0 {
            format!("[{}] +{}", branch_name, extra_count)
        } else {
            format!("[{}]", branch_name)
        };

        spans.push(Span::styled(label_text, label_style));
        spans.push(Span::raw(" "));
    }

    // Commit message
    spans.push(Span::raw(cr.commit.message.clone()));

    // Right-aligned info (date, author, hash)
    // We'll handle this by computing spaces
    let date_str = format!("  {}  ", cr.commit.date);
    let author_str = truncate_str(&cr.commit.author, 8);
    let hash_str = format!("  {}", cr.commit.short_hash);

    // Calculate current span widths to pad
    let current_len: usize = spans.iter().map(|s| s.content.chars().count()).sum();
    let right_len = date_str.chars().count() + author_str.chars().count() + hash_str.chars().count();

    if width > current_len + right_len {
        let pad = " ".repeat(width - current_len - right_len);
        spans.push(Span::raw(pad));

        spans.push(Span::styled(
            date_str,
            Style::default().fg(Color::Indexed(8)),
        ));
        spans.push(Span::styled(
            author_str,
            Style::default().fg(Color::Indexed(6)),
        ));
        spans.push(Span::styled(
            hash_str,
            Style::default().fg(Color::Indexed(3)),
        ));
    }

    let line = Line::from(spans);

    let base_style = if selected {
        Style::default().bg(Color::Indexed(8))
    } else {
        Style::default()
    };

    Paragraph::new(line).style(base_style)
}

fn get_branch_label_color(cr: &crate::graph::CommitRow, _branch_idx: usize) -> Color {
    // Use the commit's graph node color
    if let Some(node_cell) = cr.graph.cells.iter().find(|c| c.ch == '●' || c.ch == '◉') {
        Color::Indexed(node_cell.color)
    } else {
        Color::Indexed(12)
    }
}

fn build_graph_spans(cells: &[GraphCell]) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    let graph_modifier = Modifier::BOLD;

    for cell in cells {
        if cell.color == 0 {
            spans.push(Span::raw(cell.ch.to_string()));
        } else {
            let style = Style::default()
                .fg(Color::Indexed(cell.color))
                .add_modifier(graph_modifier);
            spans.push(Span::styled(cell.ch.to_string(), style));
        }
    }

    spans
}

fn build_connector_row_widget(cells: &[GraphCell], width: usize) -> Paragraph<'static> {
    let spans = build_graph_spans(cells);
    Paragraph::new(Line::from(spans)).style(Style::default().add_modifier(Modifier::BOLD))
}

fn truncate_str(s: &str, max_width: usize) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.len() <= max_width {
        // Pad with spaces
        format!("{:<width$}", s, width = max_width)
    } else {
        chars.iter().take(max_width).collect()
    }
}

fn draw_commit_detail(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title(" Commit Detail ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Indexed(8)));

    let inner = block.inner(area);

    let content = if let Some(ref detail) = app.current_detail {
        let mut lines = Vec::new();
        lines.push(Line::from(vec![
            Span::styled("Commit: ", Style::default()),
            Span::styled(detail.hash.clone(), Style::default()),
        ]));
        lines.push(Line::from(vec![
            Span::styled("Author: ", Style::default()),
            Span::styled(detail.author.clone(), Style::default()),
        ]));
        lines.push(Line::from(vec![
            Span::styled("Date:   ", Style::default()),
            Span::styled(detail.date.clone(), Style::default()),
        ]));
        if !detail.parents.is_empty() {
            lines.push(Line::from(vec![
                Span::styled("Parent: ", Style::default()),
                Span::styled(detail.parents.join(", "), Style::default()),
            ]));
        }
        lines.push(Line::raw(""));
        // Message
        for msg_line in detail.message.split('\n') {
            lines.push(Line::raw(msg_line.to_string()));
        }
        lines
    } else if let (Some(_uncommitted), true) = (&app.uncommitted, {
        let has_uncommitted = app.uncommitted.is_some();
        has_uncommitted && app.selected_idx == 0
    }) {
        let uncommitted = app.uncommitted.as_ref().unwrap();
        let mut lines = Vec::new();
        lines.push(Line::styled("Uncommitted Changes", Style::default()));
        lines.push(Line::raw(""));
        lines.push(Line::raw(format!("{} files with changes", uncommitted.file_count)));
        lines
    } else {
        vec![Line::raw("")]
    };

    let para = Paragraph::new(content).block(block);
    f.render_widget(para, area);
}

fn draw_file_changes(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title(" Changed Files ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Indexed(8)));

    let inner = block.inner(area);

    let (total_files, additions, deletions, files) = 
        if let Some(ref detail) = app.current_detail {
            (detail.total_files, detail.total_additions, detail.total_deletions, &detail.files[..])
        } else if let (Some(uncommitted), true) = (&app.uncommitted, {
            let has_uncommitted = app.uncommitted.is_some();
            has_uncommitted && app.selected_idx == 0
        }) {
            (uncommitted.file_count, uncommitted.total_additions, uncommitted.total_deletions, &uncommitted.files[..])
        } else if let Some(ref detail) = app.current_detail {
            (detail.total_files, detail.total_additions, detail.total_deletions, &detail.files[..])
        } else {
            return f.render_widget(block, area);
        };

    let mut lines = Vec::new();
    lines.push(Line::raw(format!("{} files changed  +{} -{}", total_files, additions, deletions)));
    lines.push(Line::raw(""));

    for file in files.iter().take(inner.height as usize - 2) {
        let status_color = match file.status {
            'A' => Color::Green,
            'D' => Color::Red,
            'M' => Color::Yellow,
            _ => Color::White,
        };

        let line = Line::from(vec![
            Span::styled(format!(" {} ", file.status), Style::default().fg(status_color)),
            Span::raw(format!("{} +{} -{}", file.path, file.additions, file.deletions)),
        ]);
        lines.push(line);
    }

    let para = Paragraph::new(lines).block(block);
    f.render_widget(para, area);
}

fn draw_status_bar(f: &mut Frame, app: &App, area: Rect) {
    let mode_str = match &app.mode {
        AppMode::Help => " Esc/q close help ",
        AppMode::Search => " Enter confirm  Esc cancel ",
        AppMode::NewBranch => " Enter confirm  Esc cancel ",
        AppMode::ConfirmDelete => " y: Yes  n: No ",
        AppMode::Normal => " j/k move  Enter checkout  b branch  f fetch  ? help  q quit ",
        _ => " ",
    };

    let mode_indicator = match &app.mode {
        AppMode::Help => Some("HELP"),
        AppMode::Search => Some("INPUT"),
        AppMode::NewBranch => Some("INPUT"),
        AppMode::ConfirmDelete => Some("CONFIRM"),
        _ => None,
    };

    let mut spans: Vec<Span> = Vec::new();

    // Repo name
    spans.push(Span::styled(
        format!(" {} ", app.repo_name),
        Style::default().add_modifier(Modifier::BOLD),
    ));

    // Current branch
    spans.push(Span::styled(
        format!("  {} ", app.current_branch),
        Style::default().add_modifier(Modifier::BOLD),
    ));

    // Status message or mode hint
    if let Some((msg, _)) = &app.status_message {
        spans.push(Span::styled(
            format!("  {} ", msg),
            Style::default(),
        ));
    } else {
        spans.push(Span::styled(
            mode_str.to_string(),
            Style::default(),
        ));
    }

    // Mode indicator on the right
    if let Some(indicator) = mode_indicator {
        let current_len: usize = spans.iter().map(|s| s.content.chars().count()).sum();
        let right_len = indicator.len() + 1;
        if area.width as usize > current_len + right_len {
            let pad = " ".repeat(area.width as usize - current_len - right_len);
            spans.push(Span::raw(pad));
            spans.push(Span::styled(
                indicator.to_string(),
                Style::default().add_modifier(Modifier::BOLD),
            ));
        }
    }

    let para = Paragraph::new(Line::from(spans))
        .style(Style::default());
    f.render_widget(para, area);
}

